from langchain.embeddings import EmbeddingModel

class ProductRecommender:
    def __init__(self, model_name='fasttext-v1'):
        self.model = EmbeddingModel(model=model_name)

    def get_product_embedding(self, product_description):
        return self.model.embed_text(product_description)

    def recommend_similar(self, product_description, product_catalog):
        target_embedding = self.get_product_embedding(product_description)
        similarities = []

        for product in product_catalog:
            catalog_embedding = self.get_product_embedding(product['description'])
            similarity_score = self._cosine_similarity(target_embedding, catalog_embedding)
            similarities.append((product, similarity_score))

        similarities.sort(key=lambda x: x[1], reverse=True)
        return similarities[:5]

    def _cosine_similarity(self, vec_a, vec_b):
        dot_product = sum(a * b for a, b in zip(vec_a, vec_b))
        norm_a = sum(a * a for a in vec_a) ** 0.5
        norm_b = sum(b * b for b in vec_b) ** 0.5
        return dot_product / (norm_a * norm_b)

# Example usage
if __name__ == "__main__":
    product_catalog = [
        {'id': 1, 'description': 'Ergonomic office chair with lumbar support.'},
        {'id': 2, 'description': 'Wireless noise-cancelling headphones.'},
        {'id': 3, 'description': 'Smart LED light bulb with dimmable feature.'},
        {'id': 4, 'description': 'Portable USB-C power bank with fast charging.'},
        {'id': 5, 'description': 'Bluetooth mechanical keyboard with RGB lighting.'},
    ]

    recommender = ProductRecommender()
    recommendations = recommender.recommend_similar('Comfortable office chair', product_catalog)

    for product, score in recommendations:
        print(f"Product ID: {product['id']} - Similarity Score: {score:.2f}")

