from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from langchain.agents import AgentExecutor, Tool
from langchain.tools import ToolToLangChain
from langchain.models import OpenAI
import os

app = FastAPI()

openai_api_key = os.getenv("OPENAI_API_KEY")
if not openai_api_key:
    raise RuntimeError("OPENAI_API_KEY environment variable is not set.")

# Define some mock tools for the agent
class WeatherService(Tool):
    def run(self, query: str) -> str:
        # Imagine this is a real API call
        return "The weather is sunny with a chance of rain."

class StockPriceService(Tool):
    def run(self, query: str) -> str:
        # Imagine this is a real API call
        return "The current price of ACME Corp is $125.00."

# Define the tools
tools = [
    ToolToLangChain(tool=WeatherService(), name="weather_tool"),
    ToolToLangChain(tool=StockPriceService(), name="stock_tool"),
]

# Initialize the language model
llm = OpenAI(api_key=openai_api_key, model_version="gpt-4.5")

# Create the agent executor
agent_executor = AgentExecutor(
    llm=llm,
    tools=tools
)

class QueryRequest(BaseModel):
    query: str

class QueryResponse(BaseModel):
    response: str

@app.post("/query", response_model=QueryResponse)
async def query_agent(request: QueryRequest):
    try:
        response = agent_executor.run(request.query)
        return QueryResponse(response=response)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

