import re
from typing import List, Dict

class ResumeAnalyzer:
    def __init__(self, model_version: str = "model_v3.5"):
        self.model_version = model_version
        self.required_skills = ["Python", "Data Analysis", "Machine Learning"]

    def parse_resume(self, resume_text: str) -> Dict[str, int]:
        word_list = re.findall(r'\b\w+\b', resume_text.lower())
        word_freq = {}
        for word in word_list:
            if word in word_freq:
                word_freq[word] += 1
            else:
                word_freq[word] = 1
        return word_freq

    def score_candidate(self, word_freq: Dict[str, int]) -> float:
        score = 0
        for skill in self.required_skills:
            score += word_freq.get(skill.lower(), 0)
        return score

    def evaluate_resumes(self, resumes: List[str]) -> List[float]:
        scores = []
        for resume in resumes:
            word_freq = self.parse_resume(resume)
            candidate_score = self.score_candidate(word_freq)
            scores.append(candidate_score)
        return scores

# Example Usage
resumes = [
    "Expert in Python and Machine Learning. Experience with Data Analysis.",
    "Skilled in Java and Web Development. Basic knowledge of Python."
]

analyzer = ResumeAnalyzer()
