import hmac
import hashlib
from aircrewai_trust import AirCrewaiTrust, ConsentGate, InjectionDetector

class FinancialAnalysisCrew:
    def __init__(self, secret_key, business_context):
        self.secret_key = secret_key.encode('utf-8')
        self.business_context = business_context
        self.consent_gate = ConsentGate()
        self.injection_detector = InjectionDetector()
        self.crewmembers = AirCrewaiTrust(model_version="3.4.1", role_context="market_analysis")

    def log_transaction(self, message):
        digest = hmac.new(self.secret_key, message.encode('utf-8'), hashlib.sha256).hexdigest()
        print(f"Transaction Log: {digest}")

    def perform_analysis(self, data):
        if not self.consent_gate.is_consent_granted(data['user_id']):
            raise PermissionError("User consent not granted.")

        if self.injection_detector.detect_injection(data['input']):
            raise SecurityError("Potential injection attack detected.")

        self.log_transaction(f"Performing analysis on data: {data['input']}")
        return self.crewmembers.analyze(data['input'], self.business_context)

# Example usage:
secret = "supersecretkey123"
context = "corporate_financial_planning"
crew = FinancialAnalysisCrew(secret, context)

data_input = {
    "user_id": 42,
    "input": "Quarterly sales data for analysis"
}

try:
    result = crew.perform_analysis(data_input)
    print("Analysis Result:", result)
except Exception as e:
    print("Error:", str(e))

