from crewai import Crew, Agent

class ResearchAgent(Agent):
    def define_role(self):
        return {
            "name": "Research Specialist",
            "description": "Collects and synthesizes information relevant to the project tasks."
        }

    def perform_task(self, task):
        # Simulate research task processing
        data_sources = ["https://api.example.com/data", "https://api.anotherexample.com/info"]
        research_data = {url: f"Data from {url}" for url in data_sources}
        return research_data

class WritingAgent(Agent):
    def define_role(self):
        return {
            "name": "Content Creator",
            "description": "Generates written content based on the researched data."
        }

    def perform_task(self, task):
        # Simulate writing task based on research
        research_data = task.get('research_data', {})
        content = " ".join(f"Written paragraph based on {data}" for data in research_data.values())
        return content

class ReviewAgent(Agent):
    def define_role(self):
        return {
            "name": "Quality Reviewer",
            "description": "Evaluates and provides feedback on the content for quality assurance."
        }

    def perform_task(self, task):
        # Simulate review process
        content = task.get('content', "")
        feedback = "Looks good!" if len(content) > 20 else "Needs more content."
        return feedback

class ReportGenerationSystem(Crew):
    def __init__(self):
        super().__init__(name="Report Generation System")
        self.add_agent(ResearchAgent())
        self.add_agent(WritingAgent())
        self.add_agent(ReviewAgent())

    def execute(self):
        # Define task pipeline
        research_task = self.create_task("Conduct Research")
        research_results = self.assign_task(research_task, "Research Specialist")

        writing_task = self.create_task("Create Content", research_data=research_results)
        written_content = self.assign_task(writing_task, "Content Creator")

        review_task = self.create_task("Review Content", content=written_content)
        review_feedback = self.assign_task(review_task, "Quality Reviewer")

        return {
            "content": written_content,
            "feedback": review_feedback
        }

# Instantiate and run the system
report_system = ReportGenerationSystem()
final_results = report_system.execute()
print(final_results)

import asyncio
import logging
import json
import os
from datetime import datetime
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,
    PermissionResultAllow, PermissionResultDeny,
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
os.makedirs("./audit", exist_ok=True)

DANGEROUS_COMMANDS = ["rm -rf", "sudo", "chmod 777", "mkfs"]

async def block_dangerous_bash(input_data, tool_use_id, context):
    """Block dangerous bash commands."""
    if input_data.get("tool_name") == "Bash":
        cmd = input_data.get("tool_input", {{}}).get("command", "")
        for pattern in DANGEROUS_COMMANDS:
            if pattern in cmd:
                logger.warning(f"Blocked dangerous command: {{cmd}}")
                return {{
                    "hookSpecificOutput": {{
                        "hookEventName": "PreToolUse",
                        "permissionDecision": "deny",
                        "permissionDecisionReason": f"Dangerous: {{pattern}}",
                    }}
                }}
    return {{}}

async def audit_log(input_data, tool_use_id, context):
    """Log every tool result to audit directory."""
    record = {{
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "tool": input_data.get("tool_name"),
        "tool_use_id": tool_use_id,
    }}
    fname = f"./audit/{{tool_use_id or 'unknown'}}.json"
    with open(fname, "w") as f:
        json.dump(record, f)
    return {{}}

async def permission_handler(tool_name, input_data, context):
    """Risk-based permission handler."""
    if tool_name == "Bash":
        cmd = input_data.get("command", "")
        if any(p in cmd for p in DANGEROUS_COMMANDS):
            return PermissionResultDeny(message="Blocked by policy")
    return PermissionResultAllow(updated_input=input_data)

async def main():
    options = ClaudeAgentOptions(
        allowed_tools=["Read", "Write", "Bash"],
        can_use_tool=permission_handler,
        max_turns=10,
        hooks={{
            "PreToolUse": [
                HookMatcher(matcher="Bash", hooks=[block_dangerous_bash]),
            ],
            "PostToolUse": [HookMatcher(hooks=[audit_log])],
        }},
    )
    async with ClaudeSDKClient(options=options) as client:
        await client.query("Process the pending invoice payments")
        async for message in client.receive_response():
            print(message)

asyncio.run(main())

from air_rag_trust import ProvenanceTracker, VerificationGate, ChangeMonitor
from transformers import AutoTokenizer, AutoModelForQuestionAnswering
from typing import List, Dict

class LegalDocQASystem:
    def __init__(self, source_allowlist: List[str], model_name: str = "distilbert-base-uncased", monitor_threshold: float = 0.2):
        self.tokenizer = AutoTokenizer.from_pretrained(model_name)
        self.model = AutoModelForQuestionAnswering.from_pretrained(model_name)
        self.tracker = ProvenanceTracker()
        self.verifier = VerificationGate(allowlist=source_allowlist)
        self.drift_monitor = ChangeMonitor(threshold=monitor_threshold)

    def annotate_source(self, document: str, metadata: Dict[str, str]):
        self.tracker.add_source(document, metadata)

    def verify_source(self, source: str) -> bool:
        return self.verifier.is_source_allowed(source)

    def detect_drift(self, new_data: str, baseline_data: str) -> bool:
        return self.drift_monitor.has_drifted(new_data, baseline_data)

    def answer_question(self, question: str, document: str) -> str:
        inputs = self.tokenizer.encode_plus(question, document, add_special_tokens=True, return_tensors="pt")
        input_ids = inputs["input_ids"].tolist()[0]

        outputs = self.model(**inputs)
        start_scores, end_scores = outputs.start_logits, outputs.end_logits
        answer_start = start_scores.argmax()
        answer_end = end_scores.argmax() + 1

        answer = self.tokenizer.convert_tokens_to_ids(input_ids[answer_start:answer_end])
        return self.tokenizer.decode(answer, skip_special_tokens=True)

# Example usage:
source_documents = [
    {"text": "Contract law deals with agreements between parties.", "source": "legal_database"},
    {"text": "Intellectual property rights are crucial for innovation.", "source": "legal_portal"}
]

qa_system = LegalDocQASystem(source_allowlist=["legal_database", "legal_portal"])

for doc in source_documents:
    if qa_system.verify_source(doc["source"]):
        qa_system.annotate_source(doc["text"], {"source": doc["source"]})

question = "What does contract law deal with?"
document = source_documents[0]["text"]

answer = qa_system.answer_question(question, document)
print(f"Answer: {answer}")

