from air_rag_trust import ProvenanceTracker, WriteGate, DriftDetector
from transformers import AutoModelForQuestionAnswering, AutoTokenizer, pipeline
import os

# Initialize components
source_tracker = ProvenanceTracker()
permission_gate = WriteGate(allowed_sources=['acme_legal_docs', 'trusted_legal_library'])
drift_detector = DriftDetector(threshold=0.15)
model_name = "distilbert-base-cased-distilled-squad"
tokenizer = AutoTokenizer.from_pretrained(model_name)
qa_model = AutoModelForQuestionAnswering.from_pretrained(model_name)
qa_pipeline = pipeline("question-answering", model=qa_model, tokenizer=tokenizer)

def load_documents(directory):
    documents = {}
    for filename in os.listdir(directory):
        if filename.endswith(".txt"):
            with open(os.path.join(directory, filename), 'r') as file:
                documents[filename] = file.read()
    return documents

def process_query(documents, question):
    answers = []
    for doc_name, content in documents.items():
        if permission_gate.is_allowed(doc_name):
            if drift_detector.is_stable(content):
                source_tracker.track(doc_name)
                answer = qa_pipeline({'question': question, 'context': content})
                answers.append({'document': doc_name, 'answer': answer['answer'], 'score': answer['score']})
    return sorted(answers, key=lambda x: x['score'], reverse=True)

def run_legal_qa_system(query):
    documents = load_documents("legal_docs")
    results = process_query(documents, query)
    return results

if __name__ == "__main__":
    user_query = "What are the legal requirements for establishing an LLC?"
    qa_results = run_legal_qa_system(user_query)
    for result in qa_results:
        print(f"Document: {result['document']}\nAnswer: {result['answer']}\nScore: {result['score']}\n")

