# Define a class to track provenance
class DocumentProvenanceTracker:
    def __init__(self):
        self.sources = []

    def record_source(self, source: str):
        self.sources.append(source)

    def get_sources(self) -> List[str]:
        return self.sources

# Define a class to enforce write policies
class SourceWriteGate:
    def __init__(self, allowed_sources: List[str]):
        self.allowed_sources = allowed_sources

    def is_write_allowed(self, source: str) -> bool:
        return source in self.allowed_sources

# Define a class for detecting model drift
class ModelDriftMonitor:
    def __init__(self, threshold: float):
        self.threshold = threshold
        self.current_drift = 0.0

    def update_drift(self, drift_value: float):
        self.current_drift += drift_value

    def is_drift_exceeded(self) -> bool:
        return self.current_drift > self.threshold

# Initialize the components
provenance_tracker = DocumentProvenanceTracker()
write_gate = SourceWriteGate(allowed_sources=["gov_legal", "law_firm_a", "law_firm_b"])
drift_monitor = ModelDriftMonitor(threshold=0.1)

# Define the QA system function
def legal_document_qa_system(question: str, context: str, source: str) -> Dict[str, str]:
    provenance_tracker.record_source(source)

    if not write_gate.is_write_allowed(source):
        return {"error": "Source not allowed"}

    inputs = tokenizer(question, context, return_tensors="pt")
    outputs = model(**inputs)
    answer_start_scores, answer_end_scores = outputs.start_logits, outputs.end_logits
    answer_start = answer_start_scores.argmax()
    answer_end = answer_end_scores.argmax() + 1
    answer = tokenizer.convert_tokens_to_string(tokenizer.convert_ids_to_tokens(inputs['input_ids'][0][answer_start:answer_end]))

    # Simulate drift monitoring
    drift_monitor.update_drift(0.02)
    if drift_monitor.is_drift_exceeded():
        return {"error": "Model drift detected"}

    return {"answer": answer, "sources": provenance_tracker.get_sources()}

