import hmac
import hashlib
from datetime import datetime
from typing import List, Dict, Any

class HMACLogger:
    def __init__(self, secret_key: str):
        self.secret_key = secret_key.encode()

    def log(self, message: str) -> str:
        timestamp = datetime.utcnow().isoformat()
        message_bytes = f"{timestamp} - {message}".encode()
        digest = hmac.new(self.secret_key, message_bytes, hashlib.sha256).hexdigest()
        return f"{timestamp} - {digest}"

class ConsentGate:
    def __init__(self):
        self.consent_given = False

    def request_consent(self) -> bool:
        # Simulate consent process
        self.consent_given = True
        return self.consent_given

    def check_consent(self) -> bool:
        return self.consent_given

class InjectionDetector:
    @staticmethod
    def detect_injection(input_data: str) -> bool:
        suspicious_patterns = ["--", ";", "/*", "*/", "xp_"]
        return any(pattern in input_data for pattern in suspicious_patterns)

class FinancialAgent:
    def __init__(self, name: str, model_version: str):
        self.name = name
        self.model_version = model_version

    def analyze(self, data: Dict[str, Any]) -> Dict[str, Any]:
        result = {"name": self.name, "model_version": self.model_version, "analysis": "Sample Analysis"}
        return result

class FinancialAnalysisCrew:
    def __init__(self, agents: List[FinancialAgent], logger: HMACLogger, consent_gate: ConsentGate, detector: InjectionDetector):
        self.agents = agents
        self.logger = logger
        self.consent_gate = consent_gate
        self.detector = detector

    def perform_analysis(self, financial_data: Dict[str, Any]) -> List[Dict[str, Any]]:
        if not self.consent_gate.check_consent():
            raise PermissionError("Consent not given.")

        if self.detector.detect_injection(str(financial_data)):
            raise ValueError("Potential injection detected.")

        results = []
        for agent in self.agents:
            result = agent.analyze(financial_data)
            log_entry = self.logger.log(f"Agent {agent.name} analysis complete.")
            result["log"] = log_entry
            results.append(result)

        return results

# Usage Example
hmac_logger = HMACLogger(secret_key="supersecretkey")
consent_gate = ConsentGate()
injection_detector = InjectionDetector()

agents = [
    FinancialAgent(name="AgentX", model_version="Xv1.2"),
    FinancialAgent(name="AgentY", model_version="Yv2.3")
]

crew = FinancialAnalysisCrew(agents=agents, logger=hmac_logger, consent_gate=consent_gate, detector=injection_detector)

if consent_gate.request_consent():
    financial_data = {"revenue": 1000000, "expenses": 500000}
    analysis_results = crew.perform_analysis(financial_data)
    for result in analysis_results:
        print(result)

