class RiskManager:
    def assess_risk(self, parameters):
        risk_score = self.calculate(parameters)
        risk_level = self.determine_level(risk_score)
        impact_assessment = self.assess_impact(risk_level)
        self.report(risk_score, risk_level, impact_assessment)
        return risk_level

    def calculate(self, params):
        # Calculate risk score
        return (max(params) - min(params)) / max(params)

    def determine_level(self, score):
        # Determine risk level
        if score > 0.6:
            return 'High'
        return 'Low'

    def assess_impact(self, level):
        # Assess impact
        if level == 'High':
            return 'High impact'
        return 'Low impact'

    def report(self, score, level, impact):
        # Logging risk details
        print(f"Risk Score: {score}, Level: {level}, Impact: {impact}")

