import hmac
import hashlib
import logging
from datetime import datetime

class ConsentGate:
    def __init__(self):
        self.consent_log = {}

    def obtain_consent(self, user_id):
        self.consent_log[user_id] = datetime.now()
        logging.info(f"Consent obtained for user_id: {user_id} at {self.consent_log[user_id]}")

    def check_consent(self, user_id):
        return user_id in self.consent_log

class InjectionDetector:
    def detect(self, input_data):
        if any(char in input_data for char in [';', '--', '/*', '*/', '@@']):
            raise ValueError("Detected potential injection in input data.")
        logging.info("No injection detected in input data.")

class Auditor:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def create_hmac(self, message):
        return hmac.new(self.secret_key.encode(), message.encode(), hashlib.sha256).hexdigest()

    def log_action(self, message):
        hmac_digest = self.create_hmac(message)
        logging.info(f"Action: {message}, HMAC: {hmac_digest}")

class FinancialAnalysisAgent:
    def __init__(self, consent_gate, injection_detector, auditor):
        self.consent_gate = consent_gate
        self.injection_detector = injection_detector
        self.auditor = auditor

    def perform_analysis(self, user_id, financial_data):
        if not self.consent_gate.check_consent(user_id):
            raise PermissionError("Consent not obtained for user.")

        self.injection_detector.detect(financial_data)

        analysis_result = f"Analysis for {user_id} with data: {financial_data}"
        self.auditor.log_action(analysis_result)
        return analysis_result

