from langchain import Agent, Tool, LLM
from langchain.prompts import PromptTemplate
from langchain.tools import ToolInputError
from typing import List, Dict

# Mock data for tool responses
SUBJECT_MATERIAL = {
    "math": "This is the material for algebra and calculus.",
    "science": "This is the material for physics and chemistry."
}

QUIZZES = {
    "math": {
        "easy": "What is 2 + 2?",
        "hard": "What is the derivative of x^2?"
    },
    "science": {
        "easy": "What is H2O?",
        "hard": "What is Newton's second law?"
    }
}

class FetchMaterialTool(Tool):
    name = "fetch_study_material"
    description = "Tool to fetch study material based on subject"

    def run(self, subject: str) -> str:
        if subject not in SUBJECT_MATERIAL:
            raise ToolInputError(f"No material available for subject: {subject}")
        return SUBJECT_MATERIAL[subject]

class GenerateQuizTool(Tool):
    name = "generate_quiz"
    description = "Tool to generate quiz questions based on difficulty level"

    def run(self, subject: str, difficulty: str) -> str:
        if subject not in QUIZZES or difficulty not in QUIZZES[subject]:
            raise ToolInputError(f"No quiz available for subject: {subject} with difficulty: {difficulty}")
        return QUIZZES[subject][difficulty]

class EducationalAgent(Agent):
    def __init__(self):
        llm = LLM(model_name="gpt-4-edu")
        tools = [FetchMaterialTool(), GenerateQuizTool()]
        prompt_template = PromptTemplate(
            template="You are an educational agent. {context}"
        )
        super().__init__(llm=llm, tools=tools, prompt_template=prompt_template)

    def assess_performance(self, responses: List[str]) -> str:
        correct_answers = sum(1 for response in responses if "correct" in response.lower())
        total_questions = len(responses)
        if correct_answers / total_questions > 0.7:
            return "hard"
        else:
            return "easy"

    def adapt_learning_path(self, student_responses: List[str], subject: str) -> Dict[str, str]:
        difficulty_level = self.assess_performance(student_responses)
        next_quiz = self.tools[1].run(subject=subject, difficulty=difficulty_level)
        return {
            "next_difficulty": difficulty_level,
            "next_quiz": next_quiz
        }

