        # Simulate consent request
        self.consent_records[user_id] = datetime.now()
        return True

class InjectionDetector:
    def __init__(self):
        self.keywords = ["DROP", "DELETE", "INSERT", "--", "/*", "*/"]

    def detect(self, query: str) -> bool:
        return any(keyword in query.upper() for keyword in self.keywords)

class HMACLogger:
    def __init__(self, secret: bytes):
        self.secret = secret

    def log(self, message: str) -> None:
        digest = hmac.new(self.secret, message.encode(), hashlib.sha256).hexdigest()
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        print(f"{timestamp} - {digest} - {message}")

class FinancialAgent:
    def __init__(self, agent_id: str, model_version: str):
        self.agent_id = agent_id
        self.model_version = model_version

    def perform_analysis(self, data: Dict[str, Any]) -> Dict[str, Any]:
        # Placeholder for financial analysis logic
        return {"status": "success", "detail": f"Analysis completed by {self.agent_id}"}

class AnalysisCrew:
    def __init__(self):
        self.agents: List[FinancialAgent] = []
        self.logger = HMACLogger(secret=os.urandom(32))
        self.consent_gate = ConsentGate()
        self.injection_detector = InjectionDetector()

    def add_agent(self, agent: FinancialAgent) -> None:
        self.agents.append(agent)
        self.logger.log(f"Agent {agent.agent_id} added with model version {agent.model_version}")

    def execute_analysis(self, user_id: str, data: Dict[str, Any]) -> None:
        if not self.consent_gate.request_consent(user_id):
            self.logger.log(f"Consent not granted for user {user_id}")
            return

        data_query = data.get("query", "")
        if self.injection_detector.detect(data_query):
            self.logger.log("Injection detected in the query")
            return

        for agent in self.agents:
            result = agent.perform_analysis(data)
            self.logger.log(f"Agent {agent.agent_id} completed analysis: {result}")

# Usage example
