import hmac
import hashlib
import json
from datetime import datetime
from typing import Any, Dict

# CONSTANTS
SECRET_KEY = b'your-secret-key'
BLACKBOX_COMPLIANCE = True

# HMAC Logging
def create_hmac_log(message: str) -> str:
    return hmac.new(SECRET_KEY, message.encode(), hashlib.sha256).hexdigest()

# Consent Gating
class ConsentManager:
    def __init__(self):
        self.consent_given = set()

    def request_consent(self, user_id: str) -> bool:
        # Assume consent is collected through an external process
        self.consent_given.add(user_id)
        return True

    def has_consent(self, user_id: str) -> bool:
        return user_id in self.consent_given

# Injection Detection
def detect_injection(input_data: Dict[str, Any]) -> bool:
    keywords = ["DROP", "DELETE", "INSERT", "UPDATE"]
    for key, value in input_data.items():
        if any(keyword in str(value).upper() for keyword in keywords):
            return True
    return False

# Agent Base Class
class AnalysisAgent:
    def __init__(self, agent_id: str):
        self.agent_id = agent_id
        self.consent_manager = ConsentManager()

    def perform_analysis(self, data: Dict[str, Any]) -> Dict[str, Any]:
        raise NotImplementedError("Subclasses should implement this method.")

# Specific Financial Analysis Agent
class InvestmentAnalysisAgent(AnalysisAgent):
    def perform_analysis(self, data: Dict[str, Any]) -> Dict[str, Any]:
        if not self.consent_manager.has_consent(data['user_id']):
            return {"error": "Consent not provided"}

        if detect_injection(data):
            return {"error": "Potential injection detected"}

        # Dummy analysis logic
        results = {
            'investment_score': len(data.get('transactions', [])) * 0.75,
            'risk_assessment': 'Low' if len(data.get('transactions', [])) < 5 else 'High'
        }
        return results

# Crew Management
class CrewManager:
    def __init__(self, agents: Dict[str, AnalysisAgent]):
        self.agents = agents

    def execute_financial_analysis(self, agent_id: str, user_data: Dict[str, Any]) -> Dict[str, Any]:
        if BLACKBOX_COMPLIANCE:
            log_message = f"{datetime.now()} - Agent {agent_id} executing analysis."
            log_hash = create_hmac_log(log_message)
            print(f"Log: {log_message}, HMAC: {log_hash}")

        agent = self.agents.get(agent_id)
        if agent:
            return agent.perform_analysis(user_data)
        else:
            return {"error": "Agent not found"}

# Usage Example
