    'user_id': 'user789',
    'transactions': [100, 250, 450]
}

# Request consent for the user
agents['Agent123'].consent_manager.request_consent('user789')

# Perform analysis
result = crew_manager.execute_financial_analysis('Agent123', user_data)
print(result)

