    def __init__(self):
        self.consent_log = {}

    def request_consent(self, agent_id):
        # Simulate consent request and response
        consent = True  # Assume consent is granted for example purposes
        self.consent_log[agent_id] = consent
        return consent

class InjectionDetector:
    def __init__(self):
        self.suspicious_patterns = ["DROP TABLE", "ALTER TABLE", "--", ";"]

    def detect(self, query):
        for pattern in self.suspicious_patterns:
            if pattern in query:
                return True
        return False

class HMACLogger:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def log(self, message):
        timestamp = datetime.utcnow().isoformat()
        message = f"{timestamp} - {message}"
        signature = hmac.new(self.secret_key.encode(), message.encode(), hashlib.sha256).hexdigest()
        with open("hmac_log.txt", "a") as log_file:
            log_file.write(f"{message} - {signature}\n")

class FinanceAgent:
    def __init__(self, agent_id, logger, gatekeeper, detector):
        self.agent_id = agent_id
        self.logger = logger
        self.gatekeeper = gatekeeper
        self.detector = detector

    def analyze_market_data(self, data):
        if not self.gatekeeper.request_consent(self.agent_id):
            self.logger.log(f"Consent not granted for agent {self.agent_id}")
            return

        if self.detector.detect(data):
            self.logger.log(f"Injection detected in query by agent {self.agent_id}")
            return

        # Simulate analysis
        result = {"result": "positive trend", "confidence": 0.88}
        self.logger.log(f"Agent {self.agent_id} analysis result: {json.dumps(result)}")
        return result

