import asyncio
import logging
import json
import os
from datetime import datetime
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,
    PermissionResultAllow, PermissionResultDeny,
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
os.makedirs("./audit", exist_ok=True)

DANGEROUS_COMMANDS = ["rm -rf", "sudo", "chmod 777", "mkfs"]

async def block_dangerous_bash(input_data, tool_use_id, context):
    """Block dangerous bash commands."""
    if input_data.get("tool_name") == "Bash":
        cmd = input_data.get("tool_input", {{}}).get("command", "")
        for pattern in DANGEROUS_COMMANDS:
            if pattern in cmd:
                logger.warning(f"Blocked dangerous command: {{cmd}}")
                return {{
                    "hookSpecificOutput": {{
                        "hookEventName": "PreToolUse",
                        "permissionDecision": "deny",
                        "permissionDecisionReason": f"Dangerous: {{pattern}}",
                    }}
                }}
    return {{}}

async def audit_log(input_data, tool_use_id, context):
    """Log every tool result to audit directory."""
    record = {{
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "tool": input_data.get("tool_name"),
        "tool_use_id": tool_use_id,
    }}
    fname = f"./audit/{{tool_use_id or 'unknown'}}.json"
    with open(fname, "w") as f:
        json.dump(record, f)
    return {{}}

async def permission_handler(tool_name, input_data, context):
    """Risk-based permission handler."""
    if tool_name == "Bash":
        cmd = input_data.get("command", "")
        if any(p in cmd for p in DANGEROUS_COMMANDS):
            return PermissionResultDeny(message="Blocked by policy")
    return PermissionResultAllow(updated_input=input_data)

async def main():
    options = ClaudeAgentOptions(
        allowed_tools=["Read", "Write", "Bash"],
        can_use_tool=permission_handler,
        max_turns=10,
        hooks={{
            "PreToolUse": [
                HookMatcher(matcher="Bash", hooks=[block_dangerous_bash]),
            ],
            "PostToolUse": [HookMatcher(hooks=[audit_log])],
        }},
    )
    async with ClaudeSDKClient(options=options) as client:
        await client.query("Summarize the quarterly earnings report")
        async for message in client.receive_response():
            print(message)

asyncio.run(main())

from langchain.chains import LLMChain
from langchain.llms import OpenAI
from langchain.prompts import PromptTemplate
from langchain.agents import AgentExecutor, Tool
from langchain.memory import ConversationBufferMemory
from langchain.tools import BaseTool

class AdaptiveExerciseTool(BaseTool):
    def __init__(self, domain):
        self.domain = domain

    def name(self):
        return f"exercise_generator_{self.domain}"

    def run(self, input_text):
        # Simulate generation of a new exercise based on the domain and input
        return f"Generated exercise for {self.domain}: Describe the process of {input_text}."

class FeedbackAnalysisTool(BaseTool):
    def name(self):
        return "feedback_analyzer"

    def run(self, feedback):
        # Simulate analyzing feedback to adapt future content
        if "too hard" in feedback:
            return "Reduce difficulty"
        elif "too easy" in feedback:
            return "Increase difficulty"
        else:
            return "Maintain current level"

llm = OpenAI(model="text-davinci-004")

prompt = PromptTemplate(input_variables=["student_input", "context"],
                        template="Student Input: {student_input}\nContext: {context}\nResponse:")

adaptive_learning_chain = LLMChain(llm=llm, prompt=prompt)

exercise_tool = AdaptiveExerciseTool(domain="calculus")
feedback_tool = FeedbackAnalysisTool()

tools = [
    Tool(name="Exercise Generator", func=exercise_tool.run),
    Tool(name="Feedback Analyzer", func=feedback_tool.run)
]

memory = ConversationBufferMemory()

agent_executor = AgentExecutor(
    agent=adaptive_learning_chain,
    tools=tools,
    memory=memory,
    verbose=True
)

def adapt_tutoring_system(student_input, context):
    return agent_executor.run({
        "student_input": student_input,
        "context": context
    })

