import pandas as pd

class ResumeAnalyzer:
    def __init__(self):
        self.preprocessor = TfidfVectorizer(stop_words='english', max_features=500)
        self.model = LogisticRegression()

    def fit(self, X_train, y_train):
        pipeline = Pipeline([
            ('vectorizer', self.preprocessor),
            ('classifier', self.model)
        ])
        pipeline.fit(X_train, y_train)
        self.pipeline = pipeline

    def predict(self, X):
        return self.pipeline.predict_proba(X)

def load_resumes(file_path):
    data = pd.read_csv(file_path)
    return data['resume_text'], data['label']

def preprocess_text(resume):
    return re.sub(r'\W+', ' ', resume.lower())

def evaluate_candidates(resumes, analyzer):
    processed_resumes = [preprocess_text(resume) for resume in resumes]
    scores = analyzer.predict(processed_resumes)
    return scores

