class CreditEvaluator:
    def __init__(self, api_key: str):
        self.api_key = api_key
        openai.api_key = api_key
        self.model_engine = "gpt-4-turbo"

    def fetch_financial_data(self, url: str) -> dict:
        response = requests.get(url)
        response.raise_for_status()
        return response.json()

    def generate_recommendation(self, financial_data: dict) -> str:
        prompt = (
            "Given the following financial data, provide a lending recommendation. "
            "Data: {}\nRecommendation:".format(financial_data)
        )
        response = openai.Completion.create(
            engine=self.model_engine,
            prompt=prompt,
            max_tokens=150
        )
        return response.choices[0].text.strip()

    def evaluate_applicant(self, applicant: Applicant) -> LendingRecommendation:
        financial_data = self.fetch_financial_data(applicant.financial_history_url)
        recommendation = self.generate_recommendation(financial_data)
        return LendingRecommendation(applicant_id=applicant.applicant_id, recommendation=recommendation)

