import hmac
import hashlib
import json
from datetime import datetime
from typing import Dict, Any

# Constants
HMAC_SECRET = b'supersecretkey'
CONSENT_REQUIRED = True

# Utility functions
def generate_hmac(message: str) -> str:
    return hmac.new(HMAC_SECRET, message.encode('utf-8'), hashlib.sha256).hexdigest()

def log_event(event_data: Dict[str, Any]) -> None:
    message = json.dumps(event_data, sort_keys=True)
    event_data['hmac'] = generate_hmac(message)
    with open('event_log.json', 'a') as log_file:
        json.dump(event_data, log_file)
        log_file.write('\n')

def check_consent(user_id: str) -> bool:
    # Simplified consent check for demonstration
    return CONSENT_REQUIRED and user_id in ["user_123", "user_456"]

def detect_injection(input_data: str) -> bool:
    # Basic pattern based detection
    suspicious_patterns = ["DROP TABLE", "SELECT * FROM"]
    return any(pattern in input_data.upper() for pattern in suspicious_patterns)

# CrewAI Financial Analysis System
class FinanceAgent:
    def __init__(self, user_id: str):
        self.user_id = user_id
        if not check_consent(user_id):
            raise PermissionError("Consent not granted.")
        self.events = []

    def analyze_market(self, market_data: str):
        if detect_injection(market_data):
            raise ValueError("Injection detected.")
        result = f"Analyzing market data for {self.user_id}: {market_data}"
        self.log_action('analyze_market', market_data)
        return result

    def log_action(self, action: str, data: str):
        event_data = {
            'timestamp': datetime.now().isoformat(),
            'user_id': self.user_id,
            'action': action,
            'data': data,
        }
        self.events.append(event_data)
        log_event(event_data)

# Example usage
if __name__ == '__main__':
    try:
        agent = FinanceAgent('user_123')
        print(agent.analyze_market("Stock prices analysis"))
    except (PermissionError, ValueError) as e:
        print(f"Error: {e}")

