class ConsentGate:
    def __init__(self):
        self.consent_log = {}

    def request_consent(self, user_id):
        current_time = datetime.now()
        self.consent_log[user_id] = current_time
        logging.info(f"Consent requested for user {user_id} at {current_time}")
        return True  # Simulating consent granted

