        return user_id in self.consent_log

class InjectionDetector:
    def __init__(self):
        self.patterns = ["DROP", "DELETE", "INSERT", "UPDATE"]

    def detect(self, text):
        return any(pattern in text.upper() for pattern in self.patterns)

