class BlackBoxLogger:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def log_event(self, event_type, details):
        timestamp = datetime.utcnow().isoformat()
        message = f"{timestamp}:{event_type}:{details}"
        signature = hmac.new(self.secret_key.encode(), message.encode(), hashlib.sha256).hexdigest()
        log_entry = f"{message}:{signature}"
        logging.info(log_entry)

class FinancialAnalysisCrew:
    def __init__(self, model_version, secret_key):
        self.analyzer = FinanceAnalyzer(model_version)
        self.consent_gate = ConsentGate()
        self.injection_detector = InjectionDetector()
        self.logger = BlackBoxLogger(secret_key)

    def process_request(self, user_id, request_data):
        if not self.consent_gate.check_consent(user_id):
            self.logger.log_event("consent_check_failed", f"user_id={user_id}")
            return {"error": "Consent not granted"}

        if self.injection_detector.detect(request_data):
            self.logger.log_event("injection_detected", f"user_id={user_id}, data={request_data}")
            return {"error": "Injection detected"}

        analysis_result = self.analyzer.analyze_market(request_data)
        self.logger.log_event("analysis_completed", f"user_id={user_id}, result={analysis_result}")
        return analysis_result

