import asyncio
import logging
import json
import os
from datetime import datetime
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,
    PermissionResultAllow, PermissionResultDeny,
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
os.makedirs("./audit", exist_ok=True)

DANGEROUS_COMMANDS = ["rm -rf", "sudo", "chmod 777", "mkfs"]

async def block_dangerous_bash(input_data, tool_use_id, context):
    """Block dangerous bash commands."""
    if input_data.get("tool_name") == "Bash":
        cmd = input_data.get("tool_input", {{}}).get("command", "")
        for pattern in DANGEROUS_COMMANDS:
            if pattern in cmd:
                logger.warning(f"Blocked dangerous command: {{cmd}}")
                return {{
                    "hookSpecificOutput": {{
                        "hookEventName": "PreToolUse",
                        "permissionDecision": "deny",
                        "permissionDecisionReason": f"Dangerous: {{pattern}}",
                    }}
                }}
    return {{}}

async def audit_log(input_data, tool_use_id, context):
    """Log every tool result to audit directory."""
    record = {{
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "tool": input_data.get("tool_name"),
        "tool_use_id": tool_use_id,
    }}
    fname = f"./audit/{{tool_use_id or 'unknown'}}.json"
    with open(fname, "w") as f:
        json.dump(record, f)
    return {{}}

async def permission_handler(tool_name, input_data, context):
    """Risk-based permission handler."""
    if tool_name == "Bash":
        cmd = input_data.get("command", "")
        if any(p in cmd for p in DANGEROUS_COMMANDS):
            return PermissionResultDeny(message="Blocked by policy")
    return PermissionResultAllow(updated_input=input_data)

async def main():
    options = ClaudeAgentOptions(
        allowed_tools=["Read", "Write", "Bash"],
        can_use_tool=permission_handler,
        max_turns=10,
        hooks={{
            "PreToolUse": [
                HookMatcher(matcher="Bash", hooks=[block_dangerous_bash]),
            ],
            "PostToolUse": [HookMatcher(hooks=[audit_log])],
        }},
    )
    async with ClaudeSDKClient(options=options) as client:
        await client.query("Review the latest pull request for bugs")
        async for message in client.receive_response():
            print(message)

asyncio.run(main())

import hmac
import hashlib
from datetime import datetime
from aircrewai_trust import ConsentGate, InjectionDetector

class Logger:
    def __init__(self, key):
        self.key = key

    def log_event(self, message):
        timestamp = datetime.now().isoformat()
        msg = f"{timestamp} - {message}"
        signature = hmac.new(self.key.encode(), msg.encode(), hashlib.sha256).hexdigest()
        with open("financial_analysis_log.txt", "a") as log_file:
            log_file.write(f"{msg} - {signature}\n")

class FinancialAgent:
    def __init__(self, name, model_version):
        self.name = name
        self.model_version = model_version

    def analyze_data(self, data):
        # Placeholder for data analysis logic
        return sum(data) / len(data)

class FinancialAnalysisCrew:
    def __init__(self, agents, secret_key):
        self.agents = agents
        self.logger = Logger(secret_key)
        self.consent_gate = ConsentGate()
        self.injection_detector = InjectionDetector()

    def process_financial_data(self, data, user_consent):
        if not self.consent_gate.check_consent(user_consent):
            self.logger.log_event("Consent not provided")
            raise PermissionError("User consent not provided")

        if self.injection_detector.detect(data):
            self.logger.log_event("Injection detected in data")
            raise ValueError("Potential injection detected")

        results = {}
        for agent in self.agents:
            result = agent.analyze_data(data)
            results[agent.name] = result
            self.logger.log_event(f"{agent.name} analyzed data with model {agent.model_version}: {result}")

        return results

