from typing import Any, Dict

class PatientRecordTool(Tool):
    def __init__(self, record_db):
        self.record_db = record_db

    def run(self, patient_id: str) -> Dict[str, Any]:
        return self.record_db.get(patient_id, {"error": "Patient record not found"})

class MedicalInfoTool(Tool):
    def run(self, query: str) -> str:
        # Imagine this interacts with a medical information API
        return "Medical information for query: " + query

class MedicalChatAgent(Agent):
    def __init__(self, llm, record_tool, info_tool):
        self.llm = llm
        self.record_tool = record_tool
        self.info_tool = info_tool

    def run(self, input_text: str) -> str:
        patient_id, query = self._parse_input(input_text)
        patient_record = self.record_tool.run(patient_id)
        medical_info = self.info_tool.run(query)
        return self._generate_response(patient_record, medical_info)

    def _parse_input(self, input_text: str) -> tuple:
        parts = input_text.split(':')
        if len(parts) != 2:
            return "", ""
        return parts[0].strip(), parts[1].strip()

    def _generate_response(self, patient_record: Dict[str, Any], medical_info: str) -> str:
        response = f"Patient Record: {patient_record}\nMedical Info: {medical_info}"
        return response

