import os
import re
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.linear_model import LogisticRegression
import numpy as np
import json

class ResumeEvaluator:
    def __init__(self, model_path='models/hiring_model_v2.pkl', keywords_path='config/keywords.json'):
        # Load pre-trained model
        self.model = self.load_model(model_path)
        # Load required skills and keywords
        self.keywords = self.load_keywords(keywords_path)

    def load_model(self, model_path):
        if not os.path.exists(model_path):
            raise FileNotFoundError(f"Model file {model_path} not found.")
        # Placeholder for loading a serialized model, assume pickle
        import pickle
        with open(model_path, 'rb') as model_file:
            return pickle.load(model_file)

    def load_keywords(self, keywords_path):
        if not os.path.exists(keywords_path):
            raise FileNotFoundError(f"Keywords file {keywords_path} not found.")
        with open(keywords_path, 'r') as file:
            return json.load(file)

    def preprocess_text(self, text):
        # Basic text preprocessing
        text = text.lower()
        text = re.sub(r'\s+', ' ', text)
        text = re.sub(r'[^a-z0-9 ]', '', text)
        return text

    def extract_features(self, resume_text):
        # Create a feature vector using TF-IDF
        vectorizer = TfidfVectorizer(vocabulary=self.keywords)
        processed_text = self.preprocess_text(resume_text)
        return vectorizer.fit_transform([processed_text]).toarray()

    def evaluate_resume(self, resume_text):
        features = self.extract_features(resume_text)
        score = self.model.predict_proba(features)[0][1]
        return score

    def score_candidates(self, candidate_resumes):
        results = {}
        for candidate_id, resume_text in candidate_resumes.items():
            score = self.evaluate_resume(resume_text)
            results[candidate_id] = score
        return results

