import random
import time
from threading import Thread

class Agent:
    def __init__(self, name):
        self.name = name

    def log(self, message):
        print(f"[{self.name}] {message}")

class ResearchAgent(Agent):
    def __init__(self, name):
        super().__init__(name)
        self.data_sources = ["DatabaseX", "API_Y", "ArchiveZ"]

    def conduct_research(self):
        self.log("Starting research task.")
        source = random.choice(self.data_sources)
        time.sleep(random.uniform(0.5, 1.5))
        findings = f"Findings from {source}"
        self.log(f"Completed research task. Findings: {findings}")
        return findings

class WriterAgent(Agent):
    def __init__(self, name):
        super().__init__(name)
        self.tools = ["DraftGen", "EditPlus"]

    def write_document(self, research_findings):
        self.log("Starting writing task.")
        tool = random.choice(self.tools)
        time.sleep(random.uniform(1.0, 2.0))
        document = f"Document based on {research_findings} using {tool}"
        self.log(f"Completed writing task. Document: {document}")
        return document

class ReviewAgent(Agent):
    def __init__(self, name):
        super().__init__(name)
        self.version = "ReviewBot v3.2"

    def review_document(self, document):
        self.log(f"Starting review task with {self.version}.")
        time.sleep(random.uniform(0.5, 1.0))
        feedback = f"Feedback on: {document}"
        self.log(f"Completed review task. Feedback: {feedback}")
        return feedback

def main():
    researcher = ResearchAgent("Martin the Researcher")
    writer = WriterAgent("Lara the Writer")
    reviewer = ReviewAgent("Zara the Reviewer")

    def research_task():
        return researcher.conduct_research()

    def writing_task(findings):
        return writer.write_document(findings)

    def review_task(document):
        return reviewer.review_document(document)

    findings = research_task()
    document = writing_task(findings)
    review_task(document)

if __name__ == "__main__":
    main()

