class FinancialAnalysisAgent(Agent):
    def __init__(self, name: str, key: bytes):
        super().__init__(name)
        self.key = key
        self.trust_tool = AirCrewaiTrust(model_version="v1.2.3-financial")

    def log_message(self, message: str):
        timestamp = datetime.utcnow().isoformat()
        data = f"{timestamp}:{message}".encode('utf-8')
        signature = hmac.new(self.key, data, hashlib.sha256).hexdigest()
        print(f"Log: {timestamp} | Message: {message} | Signature: {signature}")

    def consent_gating(self, user_consent: bool):
        if not user_consent:
            raise PermissionError("User consent required for operation.")
        self.log_message("User consent verified.")

    def detect_injection(self, input_data: str):
        if "<script>" in input_data or "DROP TABLE" in input_data:
            raise ValueError("Potential SQL or script injection detected.")
        self.log_message("Input data passed injection detection.")

    def analyze_data(self, data: Dict[str, Any], user_consent: bool) -> Dict[str, Any]:
        self.consent_gating(user_consent)
        self.detect_injection(str(data))
        self.log_message(f"Running analysis on data: {data}")
        # Placeholder for actual analysis logic
        results = {"summary": "Analysis complete", "details": {}}
        return results

class FinancialCrew:
    def __init__(self, agents: List[FinancialAnalysisAgent]):
        self.agents = agents

    def perform_analysis(self, financial_data: Dict[str, Any], consent: bool) -> List[Dict[str, Any]]:
        results = []
        for agent in self.agents:
            try:
                result = agent.analyze_data(financial_data, consent)
                results.append(result)
            except Exception as e:
                agent.log_message(f"Error during analysis: {e}")
        return results

