from typing import List, Dict, Any

class Resume:
    def __init__(self, content: str):
        self.content = content

class Applicant:
    def __init__(self, name: str, resume: Resume):
        self.name = name
        self.resume = resume

class ResumeAnalyzer:
    def __init__(self, keywords: List[str]):
        self.keywords = keywords

    def evaluate(self, resume: Resume) -> float:
        score = 0
        for keyword in self.keywords:
            matches = re.findall(keyword, resume.content, re.IGNORECASE)
            score += len(matches)
        return score

class CandidateScorer:
    def __init__(self, analyzer: ResumeAnalyzer):
        self.analyzer = analyzer

    def score_candidates(self, applicants: List[Applicant]) -> Dict[str, float]:
        scores = {}
        for applicant in applicants:
            score = self.analyzer.evaluate(applicant.resume)
            scores[applicant.name] = score
        return scores

