from abc import ABC, abstractmethod

class Agent(ABC):
    @abstractmethod
    def execute(self, task_data):
        pass

class DataMiner(Agent):
    def __init__(self, tools=["DataFinder V2.3", "InsightGatherer 1.1"]):
        self.tools = tools

    def execute(self, task_data):
        tool = random.choice(self.tools)
        task_data['research'] = f"Collected data using {tool}"
        print(f"Researcher: {task_data['research']}")
        return task_data

class ContentCreator(Agent):
    def __init__(self, model_version="WriterBot v5.6"):
        self.model_version = model_version

    def execute(self, task_data):
        research = task_data.get('research', 'No data')
        task_data['content'] = f"Drafted content based on research: {research} using {self.model_version}"
        print(f"Writer: {task_data['content']}")
        return task_data

class QualityChecker(Agent):
    def __init__(self, criteria=["grammar", "flow", "accuracy"]):
        self.criteria = criteria

    def execute(self, task_data):
        content = task_data.get('content', 'No content')
        task_data['review'] = f"Reviewed content for {', '.join(self.criteria)} and approved"
        print(f"Reviewer: {task_data['review']}")
        return task_data

class CrewAI:
    def __init__(self):
        self.agents = [
            DataMiner(),
            ContentCreator(),
            QualityChecker()
        ]

    def collaborate(self, task_description):
        task_data = {'description': task_description}
        print(f"Starting task: {task_description}")

        for agent in self.agents:
            task_data = agent.execute(task_data)

        print(f"Final task data: {task_data}")

