from air_rag_trust import DocumentProvenance, OutputControl, ChangeAnalyzer
from transformers import AutoTokenizer, AutoModelForQuestionAnswering
from typing import List, Dict

# Initialize components
provenance_tracker = DocumentProvenance(allowlist_sources=['legal_db', 'gov_repo'])
output_gate = OutputControl(allowed_sources=['legal_db', 'gov_repo'])
drift_detector = ChangeAnalyzer(sensitivity=0.85)

tokenizer = AutoTokenizer.from_pretrained("distilbert-base-uncased")
model = AutoModelForQuestionAnswering.from_pretrained("distilbert-base-uncased")

def verify_document_source(source: str) -> bool:
    return provenance_tracker.is_source_approved(source)

def check_output_source(output_source: str) -> bool:
    return output_gate.is_output_approved(output_source)

def detect_document_drift(document: str, historical_docs: List[str]) -> bool:
    return drift_detector.detect_drift(current_doc=document, historical_docs=historical_docs)

def answer_question(question: str, document: str) -> Dict[str, str]:
    inputs = tokenizer(question, document, return_tensors="pt")
    outputs = model(**inputs)
    answer_start = outputs.start_logits.argmax()
    answer_end = outputs.end_logits.argmax() + 1
    answer = tokenizer.convert_tokens_to_string(tokenizer.convert_ids_to_tokens(inputs.input_ids[0][answer_start:answer_end]))
    return {"answer": answer}

def legal_document_qa(document: str, source: str, question: str, historical_docs: List[str]) -> Dict[str, str]:
    if not verify_document_source(source):
        return {"error": "Document source not permitted"}

    if detect_document_drift(document, historical_docs):
        return {"error": "Significant drift detected in document content"}

    response = answer_question(question, document)

    if not check_output_source(response.get("source", "")):
        return {"error": "Output source not permitted"}

    return response

