import random
import time

class Agent:
    def __init__(self, name):
        self.name = name

    def perform_task(self):
        raise NotImplementedError("Subclasses should implement this method.")

class Researcher(Agent):
    def __init__(self, name):
        super().__init__(name)

    def perform_task(self, topic):
        print(f"[Researcher] {self.name} is researching on the topic: {topic}")
        data_sources = ['scholar', 'news', 'journals']
        data = {source: f"Data from {source}" for source in data_sources}
        time.sleep(random.uniform(0.5, 1.5))  # Simulate research time
        return data

class Writer(Agent):
    def __init__(self, name):
        super().__init__(name)

    def perform_task(self, data):
        print(f"[Writer] {self.name} is writing based on collected data.")
        content = "\n".join(f"Content from {source}: {info}" for source, info in data.items())
        time.sleep(random.uniform(0.5, 1.5))  # Simulate writing time
        return content

class Reviewer(Agent):
    def __init__(self, name):
        super().__init__(name)

    def perform_task(self, content):
        print(f"[Reviewer] {self.name} is reviewing the written content.")
        feedback = "Looks good." if random.random() > 0.3 else "Needs improvements."
        time.sleep(random.uniform(0.5, 1.5))  # Simulate review time
        return feedback

class CrewAI:
    def __init__(self, researcher, writer, reviewer):
        self.researcher = researcher
        self.writer = writer
        self.reviewer = reviewer

    def execute_task(self, topic):
        research_data = self.researcher.perform_task(topic)
        written_content = self.writer.perform_task(research_data)
        review_feedback = self.reviewer.perform_task(written_content)
        print(f"[CrewAI] Task completed. Reviewer's feedback: {review_feedback}")

