import random
from typing import Any, Dict, List

class CrewAI:
    def __init__(self, agents: List['Agent']):
        self.agents = agents

    def execute_task(self, task_desc: str):
        task_data = {}
        for agent in self.agents:
            task_data = agent.perform_task(task_desc, task_data)
        return task_data

class Agent:
    def __init__(self, name: str):
        self.name = name

    def perform_task(self, task_desc: str, data: Dict[str, Any]) -> Dict[str, Any]:
        raise NotImplementedError("This method should be implemented by subclasses.")

class Researcher(Agent):
    def perform_task(self, task_desc: str, data: Dict[str, Any]) -> Dict[str, Any]:
        research_points = [
            "Evaluate market trends",
            "Gather customer feedback",
            "Analyze competitor strategies"
        ]
        research = random.choice(research_points)
        data['research'] = research
        print(f"{self.name} (Researcher) completed: {research}")
        return data

class Writer(Agent):
    def perform_task(self, task_desc: str, data: Dict[str, Any]) -> Dict[str, Any]:
        if 'research' not in data:
            raise ValueError("Research data is missing for writing.")
        draft = f"Drafting article based on {data['research']}"
        data['draft'] = draft
        print(f"{self.name} (Writer) completed: {draft}")
        return data

class Reviewer(Agent):
    def perform_task(self, task_desc: str, data: Dict[str, Any]) -> Dict[str, Any]:
        if 'draft' not in data:
            raise ValueError("Draft data is missing for review.")
        feedback = "Approved" if random.random() > 0.5 else "Needs Revision"
        data['review'] = feedback
        print(f"{self.name} (Reviewer) completed: {feedback}")
        return data

