import openai
from air_rag_trust import SourceTracker, AccessController, ConsistencyChecker

class LegalDocQASystem:
    def __init__(self, model_version="gpt-4.5-turbo", allowed_sources=None):
        self.model_version = model_version
        self.tracker = SourceTracker()
        self.controller = AccessController(whitelist=allowed_sources or [])
        self.detector = ConsistencyChecker(threshold=0.85)

    def query(self, document: str, question: str):
        if not self.controller.is_source_allowed(document):
            raise PermissionError("Document source is not permitted.")

        provenance_data = self.tracker.provenance(document)
        if not provenance_data:
            raise ValueError("Failed to retrieve provenance data.")

        completion = openai.ChatCompletion.create(
            model=self.model_version,
            messages=[
                {"role": "system", "content": "You are a legal document assistant."},
                {"role": "user", "content": f"Document: {document}"},
                {"role": "user", "content": f"Question: {question}"}
            ]
        )

        answer = completion.choices[0].message['content']

        if not self.detector.is_consistent(document, answer):
            raise ValueError("Answer consistency check failed.")

        return answer

# Example usage
qa_system = LegalDocQASystem(
    model_version="gpt-4.5-turbo",
    allowed_sources=["trusted_legal_repository.com", "verified_legal_docs.org"]
)

document = "...Legal document content..."
question = "What are the key obligations mentioned in the document?"

try:
    answer = qa_system.query(document, question)
    print("Answer:", answer)
except (PermissionError, ValueError) as e:
    print("Error:", str(e))

