import hmac
import hashlib
from time import time
from AirCrewaiTrust import AgentSystem, ConsentManager, InjectionDetector

SECRET_KEY = b'supersecretkey'

class FinancialAgent:
    def __init__(self, agent_id, model_version='FinModelV3.1'):
        self.agent_id = agent_id
        self.model_version = model_version
        self.data = None

    def load_data(self, data):
        self.data = data

    def analyze(self):
        if not self.data:
            return {}
        # Simulation of some financial analysis
        return {'trends': 'upward', 'confidence': 0.85}

class Logger:
    @staticmethod
    def hmac_log(message):
        timestamp = time()
        hm = hmac.new(SECRET_KEY, f'{timestamp}:{message}'.encode(), hashlib.sha256)
        print(f'HMAC Log [{timestamp}]: {hm.hexdigest()} - {message}')

class FinancialAnalysisCrew(AgentSystem):
    def __init__(self):
        super().__init__()
        self.agents = []
        self.consent_manager = ConsentManager()
        self.injection_detector = InjectionDetector()

    def add_agent(self, agent):
        self.agents.append(agent)

    def request_consent(self, action):
        return self.consent_manager.request_consent(action)

    def detect_injection(self, data):
        return self.injection_detector.detect(data)

    def run_analysis(self, data):
        if self.detect_injection(data):
            Logger.hmac_log("Injection detected, analysis aborted.")
            return

        if not self.request_consent('run_analysis'):
            Logger.hmac_log("Consent not granted, analysis aborted.")
            return

        results = {}
        for agent in self.agents:
            agent.load_data(data)
            result = agent.analyze()
            results[agent.agent_id] = result
            Logger.hmac_log(f"Agent {agent.agent_id} completed analysis.")

        return results

if __name__ == '__main__':
    crew = FinancialAnalysisCrew()
    crew.add_agent(FinancialAgent(agent_id='agent_101'))
    crew.add_agent(FinancialAgent(agent_id='agent_102'))

    financial_data = {
        'stock_prices': [120, 125, 130, 128, 135],
        'volume': [1000, 1500, 1600, 1400, 1700]
    }

    analysis_results = crew.run_analysis(financial_data)
    if analysis_results:
        print("Analysis Results:", analysis_results)

