    def __init__(self, name):
        super().__init__(name)
        self.model_version = CONFIG['model_version']

    def perform_analysis(self, data):
        if consent_gate.check_permission('financial_data_access'):
            if injection_guard.detect_injection(data):
                log_with_hmac(f"Injection detected in data for agent {self.name}")
                return None
            log_with_hmac(f"Performing equity analysis for {self.name}")
            # Placeholder for actual financial analysis logic
            return {"status": "success", "analysis": "detailed equity report"}
        else:
            log_with_hmac(f"Consent not granted for {self.name}")
            return {"status": "error", "message": "Consent not granted"}

class RiskAssessmentAgent(AirCrewAgent):
    def __init__(self, name):
        super().__init__(name)
        self.model_version = CONFIG['model_version']

    def assess_risk(self, data):
        if consent_gate.check_permission('financial_data_access'):
            if injection_guard.detect_injection(data):
                log_with_hmac(f"Injection detected in data for agent {self.name}")
