        else:
            log_with_hmac(f"Consent not granted for {self.name}")
            return {"status": "error", "message": "Consent not granted"}

# Crew Controller for managing agents
class EquityCrewControl(AirCrewControl):
    def __init__(self):
        super().__init__()
        self.agents = [
            EquityAnalysisAgent("EquityAnalyzer1"),
            RiskAssessmentAgent("RiskAssessor1"),
        ]

