import hmac
import hashlib
from autogen import AIComponent

class TraceableComponent(AIComponent):
    def __init__(self, hmac_key):
        self.hmac_key = hmac_key
        self.audit_log = []

    def execute(self, command):
        result = self._execute_command(command)
        self._log_command(command, result)
        return result

    def _execute_command(self, command):
        # Simulate command execution
        return command[::-1]

    def _log_command(self, command, result):
        command_log = {'command': command, 'result': result}
        command_log['hmac'] = hmac.new(self.hmac_key.encode(), str(command_log).encode(), hashlib.sha256).hexdigest()
        self.audit_log.append(command_log)

    def check_integrity(self, command_log):
        computed_hmac = hmac.new(self.hmac_key.encode(), str({'command': command_log['command'], 'result': command_log['result']}).encode(), hashlib.sha256).hexdigest()
        return computed_hmac == command_log['hmac']

