import hmac
import hashlib
from AirCrewaiTrust import ConsentManager, InjectionDetector

# Configuration for HMAC logging
HMAC_SECRET = b'supersecretkey'

def generate_hmac(message: str, secret: bytes) -> str:
    return hmac.new(secret, message.encode(), hashlib.sha256).hexdigest()

class FinancialAnalysisAgent:
    def __init__(self, name, model_version):
        self.name = name
        self.model_version = model_version
        self.consent_manager = ConsentManager(self.name)
        self.injection_detector = InjectionDetector(self.name)

    def analyze_data(self, data):
        if not self.consent_manager.has_consent():
            raise PermissionError("Consent not granted for data analysis.")

        if self.injection_detector.is_injection_attempt(data):
            raise ValueError("Injection detected in the data.")

        # Sample financial analysis logic
        result = {"summary": f"Analysis by {self.name} using model {self.model_version}"}
        return result

    def log_action(self, message):
        action_log = generate_hmac(message, HMAC_SECRET)
        with open('action_logs.txt', 'a') as log_file:
            log_file.write(f"{self.name}: {action_log}\n")

class CrewCoordinator:
    def __init__(self, agents):
        self.agents = agents

    def coordinate_analysis(self, dataset):
        results = {}
        for agent in self.agents:
            agent_name = agent.name
            agent.log_action(f"Starting analysis with {agent_name}")
            try:
                results[agent_name] = agent.analyze_data(dataset)
            except (PermissionError, ValueError) as e:
                agent.log_action(f"Error during analysis: {e}")
        return results

