class InsuranceClaimAgent(Agent):
    def __init__(self):
        super().__init__()
        self.model = Model(version="2.6.1")
        self.tools = [
            Tool(name="DocAnalyzer", function=self.analyze_documents),
            Tool(name="RiskAssessor", function=self.assess_risk),
            Tool(name="PayoutCalculator", function=self.calculate_payout)
        ]

    def analyze_documents(self, claim_documents):
        document_data = []
        for doc in claim_documents:
            data = self.model.process(Document(content=doc.content))
            document_data.append(data)
        return document_data

    def assess_risk(self, document_data):
        risk_score = 0
        for data in document_data:
            risk_score += data.get("risk_score", 0)
        return risk_score / len(document_data) if document_data else 0

    def calculate_payout(self, risk_score):
        base_payout = 10000  # Base payout in dollars
        adjustment_factor = max(0, 1 - risk_score / 100)
        recommended_payout = base_payout * adjustment_factor
        return recommended_payout

    def process_claim(self, claim_documents):
        document_data = self.tools[0].function(claim_documents)
        risk_score = self.tools[1].function(document_data)
        payout = self.tools[2].function(risk_score)
        return {
            "risk_score": risk_score,
            "recommended_payout": payout
        }

import openai
from datetime import datetime
from typing import List, Dict

# Set up OpenAI API key
openai.api_key = 'your-openai-api-key'

class FinancialAgent:
    def __init__(self, model_version: str = "gpt-3.5-turbo"):
        self.model_version = model_version

    def analyze_records(self, financial_data: List[Dict]) -> List[Dict]:
        recommendations = []
        for record in financial_data:
            prompt = self._create_prompt(record)
            response = self._query_openai(prompt)
            recommendation = self._parse_response(response, record['client_id'])
            recommendations.append(recommendation)
        return recommendations

    def _create_prompt(self, record: Dict) -> str:
        return (
            f"Client ID: {record['client_id']}\n"
            f"Annual Income: ${record['annual_income']}\n"
            f"Credit Score: {record['credit_score']}\n"
            f"Debt-to-Income Ratio: {record['debt_to_income_ratio']}\n"
            f"Employment Status: {record['employment_status']}\n"
            f"Current Date: {datetime.now().strftime('%Y-%m-%d')}\n"
            "Based on this financial profile, should the client be approved for a loan? "
            "Provide a recommendation (Approve/Deny) with reasoning."
        )

    def _query_openai(self, prompt: str) -> str:
        try:
            response = openai.ChatCompletion.create(
                model=self.model_version,
                messages=[{"role": "system", "content": prompt}]
            )
            return response.choices[0].message['content'].strip()
        except openai.error.OpenAIError as e:
            return f"Error: {str(e)}"

    def _parse_response(self, response: str, client_id: str) -> Dict:
        recommendation = "Unknown"
        reasoning = "No valid response received."
        if "Approve" in response:
            recommendation = "Approve"
            reasoning = response.split("Approve", 1)[-1].strip()
        elif "Deny" in response:
            recommendation = "Deny"
            reasoning = response.split("Deny", 1)[-1].strip()

        return {
            "client_id": client_id,
            "recommendation": recommendation,
            "reasoning": reasoning
        }

