import hmac
import hashlib
from datetime import datetime
from typing import List, Any

class ConsentGate:
    def __init__(self):
        self.consent = {}

    def request_consent(self, user_id: str) -> bool:
        # Mocking consent request
        self.consent[user_id] = True
        return self.consent[user_id]

    def check_consent(self, user_id: str) -> bool:
        return self.consent.get(user_id, False)

class InjectionDetector:
    @staticmethod
    def detect_payload_injection(payload: str) -> bool:
        # Mocked detection logic
        prohibited_keywords = ["DROP", "DELETE", "UPDATE"]
        return any(keyword in payload.upper() for keyword in prohibited_keywords)

class HMACLogger:
    def __init__(self, secret_key: bytes):
        self.secret_key = secret_key

    def log_message(self, message: str) -> str:
        timestamp = datetime.now().isoformat()
        message_to_hash = f"{timestamp}:{message}".encode('utf-8')
        digest = hmac.new(self.secret_key, message_to_hash, hashlib.sha256).hexdigest()
        return f"{timestamp}:{digest}"

class FinancialAnalystAgent:
    def __init__(self, user_id: str, model_version: str, consent_gate: ConsentGate):
        self.user_id = user_id
        self.model_version = model_version
        self.consent_gate = consent_gate

    def perform_analysis(self, data: List[Any]) -> str:
        if not self.consent_gate.check_consent(self.user_id):
            return "Consent not provided."

        # Simulated analysis process
        return f"Analysis complete for user {self.user_id} using model {self.model_version}."

class FinancialAnalysisCrew:
    def __init__(self, secret_key: bytes):
        self.consent_gate = ConsentGate()
        self.logger = HMACLogger(secret_key)
        self.agents = []

    def add_agent(self, user_id: str, model_version: str):
        agent = FinancialAnalystAgent(user_id, model_version, self.consent_gate)
        self.agents.append(agent)

    def process_data(self, user_id: str, payload: str, data: List[Any]) -> str:
        if InjectionDetector.detect_payload_injection(payload):
            log_entry = self.logger.log_message(f"Injection detected in payload: {payload}")
            return f"Injection detected. Details logged: {log_entry}"

        if not self.consent_gate.request_consent(user_id):
            return "Consent request failed."

        for agent in self.agents:
            if agent.user_id == user_id:
                result = agent.perform_analysis(data)
                log_entry = self.logger.log_message(result)
                return f"{result}. Log entry: {log_entry}"

        return "Agent not found."

