from langchain.embeddings import OpenAIEmbeddings

def generate_document_embeddings(documents):
    # Initialize the OpenAIEmbeddings with specific model version
    embedding_model = OpenAIEmbeddings(model="text-similarity-babbage-001")

    # Create a dictionary to store document embeddings
    doc_embeddings = {}

    # Generate embeddings for each document
    for doc_id, content in documents.items():
        embeddings = embedding_model.embed([content])
        doc_embeddings[doc_id] = embeddings[0]

    return doc_embeddings

def compliance_check(embeddings, threshold=0.8):
    compliance_results = {}

    # Assess compliance based on embedding similarity
    for doc_id, vector in embeddings.items():
        similarity_score = sum(vector) / len(vector)  # Simplistic similarity computation
        compliance_results[doc_id] = similarity_score >= threshold

    return compliance_results

if __name__ == "__main__":
    # Example documents in a hypothetical legal context
    legal_documents = {
        "contract_01": "This contract outlines the terms of service between...",
        "contract_02": "The party agrees to the terms specified in the...",
        "contract_03": "The agreement is made on the 1st day of...",
    }

    # Generate embeddings for the documents
    embeddings = generate_document_embeddings(legal_documents)

    # Perform compliance check
    compliance_results = compliance_check(embeddings)

    for doc_id, is_compliant in compliance_results.items():
        status = "Compliant" if is_compliant else "Non-compliant"
        print(f"Document '{doc_id}' is {status}.")

