    def hmac_log(self, message: str):
        timestamp = datetime.utcnow().isoformat()
        digest = hmac.new(self.secret_key, msg=message.encode(), digestmod=hashlib.sha256).hexdigest()
        self.trust_comp.log_event({"timestamp": timestamp, "message": message, "digest": digest})

