            raise PermissionError("User consent not obtained.")

        for entry in data:
            if self.trust_comp.detect_injection(entry):
                raise ValueError("Data injection detected.")

        self.hmac_log("Analysis started.")
        market_analysis = self.market_analyzer.analyze_market(data)
        self.hmac_log("Market analysis completed.")

        risk_evaluation = self.risk_evaluator.evaluate_risk(data)
        self.hmac_log("Risk evaluation completed.")

        return {"market_analysis": market_analysis, "risk_evaluation": risk_evaluation}

