import os
from langchain.embeddings import OpenAIEmbeddings

def load_text_data(file_path):
    with open(file_path, 'r', encoding='utf-8') as file:
        return file.readlines()

def generate_embeddings(text_data):
    embedding_model = OpenAIEmbeddings(openai_api_key=os.getenv('OPENAI_API_KEY'), model_name='text-embedding-ada-003')
    return [embedding_model.embed(text) for text in text_data]

def save_embeddings(embeddings, output_file):
    with open(output_file, 'w', encoding='utf-8') as file:
        for embedding in embeddings:
            file.write(','.join(map(str, embedding)) + '\n')

if __name__ == "__main__":
    input_file = 'customer_feedback.txt'
    output_file = 'customer_feedback_embeddings.csv'

    raw_text_data = load_text_data(input_file)
    text_embeddings = generate_embeddings(raw_text_data)
    save_embeddings(text_embeddings, output_file)

