class Applicant:
    def __init__(self, name: str, resume: str):
        self.name = name
        self.resume = resume

class ResumeEvaluator:
    def __init__(self, model_version: str):
        self.model_version = model_version

    def _extract_skills(self, resume: str) -> List[str]:
        # Simple regex-based skill extraction (for demonstration purposes)
        skills = re.findall(r'\b(?:Python|Java|SQL|AWS|Docker|Kubernetes)\b', resume, re.IGNORECASE)
        return [skill.lower() for skill in skills]

    def score_applicant(self, applicant: Applicant) -> float:
        # ChatGPT-based scoring demonstration (requires valid credentials)
        response = openai.Completion.create(
            model=self.model_version,
            prompt=f"Score this applicant based on skills: {applicant.resume}",
            max_tokens=50
        )
        score_text = response.choices[0].text.strip()
        try:
            score = float(score_text)
        except ValueError:
            score = 0.0
        return score

class HiringPipeline:
    def __init__(self, evaluator: ResumeEvaluator):
        self.evaluator = evaluator

    def process_applicants(self, applicants: List[Applicant]) -> List[tuple]:
        scored_candidates = []
        for applicant in applicants:
            score = self.evaluator.score_applicant(applicant)
            scored_candidates.append((applicant.name, score))
        scored_candidates.sort(key=lambda x: x[1], reverse=True)
        return scored_candidates

