import re
import openai

class ResumeAnalyzer:
    def __init__(self, api_key):
        openai.api_key = api_key
        self.model_id = "gpt-4"

    def score_resume(self, resume_text):
        response = openai.Completion.create(
            engine=self.model_id,
            prompt=self._generate_prompt(resume_text),
            max_tokens=150,
            temperature=0.0
        )
        score = self._extract_score(response.choices[0].text)
        return score

    def _generate_prompt(self, text):
        return (
            "Evaluate the following resume based on relevant experience, "
            "skills, and qualifications. Provide a score between 0 to 100. "
            f"Resume: {text}"
        )

    def _extract_score(self, response_text):
        score_match = re.search(r"\b(\d{1,3})\b", response_text)
        if score_match:
            score = int(score_match.group(1))
            return min(max(score, 0), 100)
        return 0

