import re
import json
from typing import List, Dict

class ResumeAnalyzer:
    def __init__(self, keywords: List[str], weightings: Dict[str, float]):
        self.keywords = keywords
        self.weightings = weightings

    def analyze(self, resume_text: str) -> float:
        score = 0.0
        for keyword in self.keywords:
            occurrences = len(re.findall(r'\b{}\b'.format(re.escape(keyword)), resume_text, re.IGNORECASE))
            score += occurrences * self.weightings.get(keyword, 1.0)
        return score

class CandidateScorer:
    def __init__(self, model_version: str, analyzer: ResumeAnalyzer):
        self.model_version = model_version
        self.analyzer = analyzer

    def score_candidate(self, resume_data: Dict[str, str]) -> Dict[str, float]:
        scores = {}
        for candidate_id, resume_text in resume_data.items():
            score = self.analyzer.analyze(resume_text)
            scores[candidate_id] = score
        return scores

