import hmac
import hashlib
import json
from datetime import datetime
from typing import Dict, Any

# Configuration constants
SECRET_KEY = b'secret-for-hmac'
LOG_FILE = 'activity.log'
CONSENT_FILE = 'consent.json'
INJECTION_SIGNATURE = 'injection_detected'
TRUSTED_MODELS = ['Model-X1', 'Model-Y2']
BUSINESS_CONTEXT = 'stock_market_analysis'

class CrewAI:
    def __init__(self):
        self.agents = []
        self.load_consent()

    def load_consent(self):
        try:
            with open(CONSENT_FILE, 'r') as f:
                self.consent_data = json.load(f)
        except FileNotFoundError:
            self.consent_data = {}

    def check_consent(self, agent_id: str) -> bool:
        return self.consent_data.get(agent_id, {}).get('consent', False)

    def log_activity(self, agent_id: str, activity: str):
        timestamp = datetime.utcnow().isoformat()
        log_entry = f'{timestamp} - {agent_id}: {activity}'
        self._hmac_log(log_entry)

    def _hmac_log(self, entry: str):
        hmac_entry = hmac.new(SECRET_KEY, entry.encode(), hashlib.sha256).hexdigest()
        with open(LOG_FILE, 'a') as log_file:
            log_file.write(f'{entry} - HMAC: {hmac_entry}\n')

    def detect_injection(self, data: Dict[str, Any]) -> bool:
        for key, value in data.items():
            if INJECTION_SIGNATURE in str(value):
                return True
        return False

    def add_agent(self, agent):
        if agent.model_version in TRUSTED_MODELS:
            self.agents.append(agent)
        else:
            raise ValueError(f"Untrusted model version: {agent.model_version}")

    def execute_analysis(self, financial_data: Dict[str, Any]):
        if self.detect_injection(financial_data):
            self.log_activity('system', 'Injection detected')
            raise ValueError("Potential injection detected in input data.")

        results = []
        for agent in self.agents:
            if not self.check_consent(agent.agent_id):
                self.log_activity(agent.agent_id, 'Consent not given')
                continue

            result = agent.analyze(financial_data)
            self.log_activity(agent.agent_id, f'Analysis complete: {result}')
            results.append(result)

        return results

class FinancialAgent:
    def __init__(self, agent_id: str, model_version: str):
        self.agent_id = agent_id
        self.model_version = model_version

    def analyze(self, data: Dict[str, Any]) -> Dict[str, Any]:
        # Placeholder for actual financial analysis logic
        analysis_result = {
            'agent_id': self.agent_id,
            'summary': 'Positive trends detected',
            'details': data
        }
        return analysis_result

