import time
from typing import List, Any

# Define the roles and their tasks
class Researcher:
    def __init__(self):
        self.role = "Researcher"

    def perform_task(self, topic: str) -> dict:
        print(f"[{self.role}] Researching on topic: {topic}")
        time.sleep(1)
        research_output = {
            "topic": topic,
            "data": "In-depth analysis and data on the topic",
            "references": ["Reference1", "Reference2", "Reference3"]
        }
        return research_output

class Writer:
    def __init__(self):
        self.role = "Writer"

    def perform_task(self, research_data: dict) -> str:
        print(f"[{self.role}] Writing content based on research data.")
        time.sleep(1)
        written_content = f"Comprehensive article on {research_data['topic']} utilizing {research_data['data']}."
        return written_content

class Reviewer:
    def __init__(self):
        self.role = "Reviewer"

    def perform_task(self, content: str) -> str:
        print(f"[{self.role}] Reviewing the content.")
        time.sleep(1)
        reviewed_content = f"Reviewed and approved content: {content}"
        return reviewed_content

# Define the collaborative task
class CollaborativeTask:
    def __init__(self, topic: str):
        self.topic = topic
        self.researcher = Researcher()
        self.writer = Writer()
        self.reviewer = Reviewer()

    def execute(self) -> str:
        research_data = self.researcher.perform_task(self.topic)
        written_content = self.writer.perform_task(research_data)
        final_content = self.reviewer.perform_task(written_content)
        return final_content

# Main function to simulate the multi-agent system
def main():
    topic_of_interest = "Impact of AI on Financial Markets"
    task = CollaborativeTask(topic_of_interest)
    result = task.execute()
    print("Final Output:")
    print(result)

if __name__ == "__main__":
    main()

