# Define the agent chain
class AgentChain(Chain):
    def __init__(self, llm, prompt_template, tools):
        self.llm = llm
        self.prompt_template = prompt_template
        self.tools = tools

    def run(self, query: str) -> str:
        formatted_prompt = self.prompt_template.format(query=query)
        tool_name = self.llm(formatted_prompt).strip()
        if tool_name in self.tools:
            return self.tools[tool_name].run(query)
        return "No appropriate tool found."

