import re
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.svm import SVC
import numpy as np
import pickle

class ResumeProcessor:
    def __init__(self, model_path):
        with open(model_path, 'rb') as file:
            self.model = pickle.load(file)
        self.vectorizer = TfidfVectorizer(stop_words='english', max_features=500)

    def preprocess(self, resume_text):
        resume_text = re.sub(r'\s+', ' ', resume_text)
        resume_text = resume_text.lower()
        return resume_text

    def vectorize(self, processed_texts):
        return self.vectorizer.fit_transform(processed_texts).toarray()

    def score_candidates(self, resumes):
        processed = [self.preprocess(resume) for resume in resumes]
        features = self.vectorize(processed)
        return self.model.predict(features)

class RecruitmentAI:
    def __init__(self, model_file):
        self.processor = ResumeProcessor(model_file)

    def evaluate_applicants(self, resume_texts):
        scores = self.processor.score_candidates(resume_texts)
        return [{"resume": resume, "score": score} for resume, score in zip(resume_texts, scores)]

def main():
    model_filename = 'svc_model_v5.pkl'
    resumes = [
        "Alice: Expert in Python, Machine Learning, and Data Analysis.",
        "Bob: Experienced in Java, Cloud Computing, and Microservices.",
        "Charlie: Skilled in Frontend Development with Angular and React."
    ]

    recruitment_system = RecruitmentAI(model_filename)
    results = recruitment_system.evaluate_applicants(resumes)

    for result in results:
        print(f"Resume: {result['resume'][:30]}... Score: {result['score']}")

if __name__ == '__main__':
    main()

