import hmac
import hashlib
from datetime import datetime

class AirCrewaiTrust:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def generate_hmac(self, message):
        return hmac.new(self.secret_key.encode(), message.encode(), hashlib.sha256).hexdigest()

class ConsentGate:
    def __init__(self):
        self.consent_log = []

    def log_consent(self, user_id, consent_given):
        self.consent_log.append((user_id, consent_given, datetime.now()))

    def has_consent(self, user_id):
        return any(log for log in self.consent_log if log[0] == user_id and log[1] == True)

class InjectionDetection:
    @staticmethod
    def detect_injection(input_data):
        suspicious_patterns = ['DROP TABLE', '--', ';', '/*', '*/', '@@']
        return any(pattern in input_data for pattern in suspicious_patterns)

class FinancialAnalysisCrew:
    def __init__(self, trust_key):
        self.trust_protocol = AirCrewaiTrust(trust_key)
        self.consent_manager = ConsentGate()
        self.injection_detector = InjectionDetection()
        self.analysis_tools = {
            'RiskModelV2': lambda x: x * 0.3,
            'ProfitAnalyzerV3': lambda x: x * 1.2
        }

    def log_action(self, action):
        message_hmac = self.trust_protocol.generate_hmac(action)
        print(f"Action HMAC: {message_hmac}")

    def perform_analysis(self, user_id, financial_data):
        if not self.consent_manager.has_consent(user_id):
            raise PermissionError("User consent not granted.")

        if self.injection_detector.detect_injection(financial_data):
            raise ValueError("Potential injection detected.")

        financial_data = float(financial_data)  # Ensure conversion to float

        results = {}
        for tool_name, tool_func in self.analysis_tools.items():
            result = tool_func(financial_data)
            results[tool_name] = result
            self.log_action(f"{tool_name} analysis completed with result: {result}")

        return results

