from threading import Thread, Event
from queue import Queue
import random
import time

class Task:
    def __init__(self, description):
        self.description = description
        self.completed = False

class TeamMember(Thread):
    def __init__(self, role, task_queue, complete_event):
        super().__init__()
        self.role = role
        self.task_queue = task_queue
        self.complete_event = complete_event

    def run(self):
        while not self.complete_event.is_set():
            try:
                task = self.task_queue.get(timeout=1)
                self.perform_task(task)
                self.task_queue.task_done()
            except:
                continue

    def perform_task(self, task):
        raise NotImplementedError

class Analyst(TeamMember):
    def perform_task(self, task):
        print(f"{self.role}: Analyzing requirements for '{task.description}'")
        time.sleep(random.uniform(0.5, 1.5))
        task.research_data = f"Research data for {task.description}"
        print(f"{self.role}: Analysis completed for '{task.description}'")

class Author(TeamMember):
    def perform_task(self, task):
        if hasattr(task, 'research_data'):
            print(f"{self.role}: Writing content for '{task.description}'")
            time.sleep(random.uniform(1.0, 2.0))
            task.written_content = f"Content for {task.description} using {task.research_data}"
            print(f"{self.role}: Writing completed for '{task.description}'")
        else:
            print(f"{self.role}: Waiting for research data for '{task.description}'")

class Auditor(TeamMember):
    def perform_task(self, task):
        if hasattr(task, 'written_content'):
            print(f"{self.role}: Reviewing content for '{task.description}'")
            time.sleep(random.uniform(0.5, 1.0))
            task.completed = True
            print(f"{self.role}: Review completed for '{task.description}'")

def main():
    task_queue = Queue()
    complete_event = Event()

    tasks = [Task(f"Project #{i}") for i in range(1, 6)]
    for task in tasks:
        task_queue.put(task)

    members = [
        Analyst("Analyst", task_queue, complete_event),
        Author("Author", task_queue, complete_event),
        Auditor("Auditor", task_queue, complete_event)
    ]

    for member in members:
        member.start()

    task_queue.join()
    complete_event.set()

    for member in members:
        member.join()

if __name__ == "__main__":
    main()

