    def __init__(self, secret_key):
        self.secret_key = secret_key

    def hmac_log(self, message):
        timestamp = datetime.utcnow().isoformat()
        msg = f"{timestamp} - {message}"
        hmac_digest = hmac.new(self.secret_key.encode(), msg.encode(), hashlib.sha256).hexdigest()
        self.write_log(f"{msg} - HMAC: {hmac_digest}")

