        super().__init__(tools=tools, llm_chain=chain)

    def decide_tool(self, task):
        if "math" in task:
            return "math_solver"
        elif "science" in task:
            return "science_explainer"
        elif "history" in task:
            return "history_narrator"
        else:
            return None

    def handle_task(self, task):
        tool_name = self.decide_tool(task)
        tool = self.tools.get(tool_name)
        if tool:
            return tool.run(task)
        else:
            return "I'm sorry, I can't handle this task."

