class PerformanceAdaptiveAgent:
    def __init__(self):
        self.agent = LangChainAgent(model=GPT4LangModel(model_name="gpt-4.0-turbo"))
        self.tools = {
            'MathMaster': Tool(name='MathMaster', description='Solves complex math problems'),
            'HistoryHelper': Tool(name='HistoryHelper', description='Provides historical context and analysis'),
            'ScienceSage': Tool(name='ScienceSage', description='Explains scientific concepts and experiments')
        }

    def assess_performance(self, student_responses):
        performance_score = sum(response['correct'] for response in student_responses) / len(student_responses)
        return performance_score

    def adapt_to_performance(self, performance_score):
        if performance_score > 0.8:
            return self.tools['MathMaster']
        elif performance_score > 0.5:
            return self.tools['ScienceSage']
        else:
            return self.tools['HistoryHelper']

    def run_session(self, student_responses):
        performance_score = self.assess_performance(student_responses)
        selected_tool = self.adapt_to_performance(performance_score)
        response = self.agent.run(selected_tool)
        return response

