from crewai import Team, Agent, TaskEnvironment
from crewai.tools import ResearchTool, WritingTool, ReviewTool
from crewai.models import LanguageModelV2

class ResearcherAgent(Agent):
    def define_role(self):
        return "Researcher responsible for gathering data and information."

    def perform_task(self, task_description):
        research_tool = ResearchTool("DataMiner")
        data = research_tool.collect_data(task_description)
        return data

class WriterAgent(Agent):
    def define_role(self):
        return "Writer responsible for drafting the document based on research."

    def perform_task(self, research_data):
        writing_tool = WritingTool("DraftMaster")
        draft = writing_tool.create_document(research_data)
        return draft

class ReviewerAgent(Agent):
    def define_role(self):
        return "Reviewer responsible for quality assurance and final edits."

    def perform_task(self, document_draft):
        review_tool = ReviewTool("CritiquePro")
        final_document = review_tool.review_document(document_draft)
        return final_document

class ContentCreationTeam(Team):
    def __init__(self):
        super().__init__()
        self.environment = TaskEnvironment()
        self.add_agent('researcher', ResearcherAgent(LanguageModelV2()))
        self.add_agent('writer', WriterAgent(LanguageModelV2()))
        self.add_agent('reviewer', ReviewerAgent(LanguageModelV2()))

    def execute_task(self, task_description):
        research_data = self.agents['researcher'].perform_task(task_description)
        document_draft = self.agents['writer'].perform_task(research_data)
        final_document = self.agents['reviewer'].perform_task(document_draft)
        return final_document

if __name__ == "__main__":
    team = ContentCreationTeam()
    task_description = "Analyze market trends for eco-friendly packaging solutions."
    final_output = team.execute_task(task_description)
    print("Final Document:", final_output)

