from typing import List, Dict
import random

# Define the base class for an agent
class Agent:
    def __init__(self, name: str, role: str):
        self.name = name
        self.role = role

    def perform_task(self, task_data: Dict) -> Dict:
        raise NotImplementedError

# Researcher agent that performs initial data gathering
class DataCollector(Agent):
    def __init__(self, name: str):
        super().__init__(name, "Researcher")

    def perform_task(self, task_data: Dict) -> Dict:
        data_sources = ["journal_articles", "industry_reports", "surveys"]
        gathered_data = {source: f"Data from {source}" for source in data_sources}
        return {"research_data": gathered_data}

# Writer agent that synthesizes the gathered data into a draft
class ContentCreator(Agent):
    def __init__(self, name: str):
        super().__init__(name, "Writer")

    def perform_task(self, task_data: Dict) -> Dict:
        research_data = task_data.get("research_data", {})
        draft = "Draft document based on: " + ", ".join(research_data.keys())
        return {"draft_content": draft}

# Reviewer agent that critiques and suggests improvements to the draft
class QualityAnalyst(Agent):
    def __init__(self, name: str):
        super().__init__(name, "Reviewer")

    def perform_task(self, task_data: Dict) -> Dict:
        draft_content = task_data.get("draft_content", "")
        feedback = f"Feedback on draft: Add more data on {random.choice(['market trends', 'case studies', 'statistical analysis'])}."
        return {"feedback": feedback}

# Simulate the multi-agent collaboration
def execute_project():
    researcher = DataCollector(name="Alice")
    writer = ContentCreator(name="Bob")
    reviewer = QualityAnalyst(name="Charlie")

    # Phase 1: Researcher gathers data
    research_results = researcher.perform_task({})
    print(f"{researcher.name}'s gathered data: {research_results}")

    # Phase 2: Writer creates draft based on research data
    draft_results = writer.perform_task(research_results)
    print(f"{writer.name}'s draft content: {draft_results}")

    # Phase 3: Reviewer provides feedback on the draft
    review_feedback = reviewer.perform_task(draft_results)
    print(f"{reviewer.name}'s feedback: {review_feedback}")

# Initiate the project execution
if __name__ == "__main__":
    execute_project()

