def authenticate_request(request_data, hmac_secret):
    message = json.dumps(request_data, sort_keys=True).encode()
    request_hmac = request_data.get('hmac')
    calculated_hmac = hmac.new(hmac_secret.encode(), message, hashlib.sha256).hexdigest()
    return hmac.compare_digest(request_hmac, calculated_hmac)

