compliance_system = FinancialCompliance(secret_key)
log_system = LogSystem()
consent_system = ConsentGate()
injection_detector = InjectionDetector()

# Consent Obtaining
consent_system.obtain_consent()

# Multi-agent system
agents = [
    FinancialAgent("RevenueAnalyzer", compliance_system, log_system, consent_system, injection_detector),
    FinancialAgent("CostEvaluator", compliance_system, log_system, consent_system, injection_detector),
    FinancialAgent("ProfitPredictor", compliance_system, log_system, consent_system, injection_detector)
]

# Simulate analysis task by each agent
def perform_analysis(agent, data):
    try:
        result = agent.analyze(data)
        print(f"{agent.name} Result: {json.dumps(result)}")
    except Exception as e:
        print(f"{agent.name} Error: {str(e)}")

data_to_analyze = "financial data string"
threads = []

for agent in agents:
    thread = threading.Thread(target=perform_analysis, args=(agent, data_to_analyze))
    threads.append(thread)
    thread.start()

for thread in threads:
