            return f"The result is {result}."
        except Exception as e:
            return f"Error in calculation: {str(e)}."

class HistoryTool(Tool):
    def execute(self, query: str) -> str:
        # Simulate a history fact retrieval
        history_facts = {
            "american revolution": "The American Revolution was a colonial revolt between 1765 and 1783.",
            "world war 2": "World War II lasted from 1939 to 1945 and involved many of the world's countries.",
        }
        return history_facts.get(query.lower(), "No facts available for this topic.")

