    template="Provide a brief overview of the topic: {topic}.",
    input_variables=["topic"]
)

# Implement the education agent
class AdaptiveTutorAgent(Agent):
    def __init__(self, llm, tools):
        super().__init__(llm=llm, tools=tools)
        self.performance_score = 0

    def adjust_difficulty(self):
        if self.performance_score < 3:
            return "easy"
        elif self.performance_score < 7:
            return "medium"
        else:
            return "hard"

    def handle_input(self, user_input: str, subject: str) -> str:
        difficulty = self.adjust_difficulty()
        if subject == "math":
            chain = LLMChain(llm=self.llm, prompt_template=math_prompt)
            response = chain.run(problem=user_input)
        elif subject == "history":
            chain = LLMChain(llm=self.llm, prompt_template=history_prompt)
            response = chain.run(topic=user_input)
        else:
            response = "Subject not supported."

        # Simulate performance tracking
        self.performance_score += 1 if "correct" in response.lower() else -1
        return response

# Instantiate the agent with necessary tools
