class InjectionDetector:
    def detect_injection(self, payload: str) -> bool:
        # Simple injection detection logic
        suspicious_patterns = ["DROP TABLE", "--", ";--", ";", "/*", "*/", "@@", "@", "char", "nchar", "varchar", "nvarchar"]
        return any(pattern in payload.upper() for pattern in suspicious_patterns)

class HMACLogger:
    def __init__(self, secret_key: str):
        self.secret_key = secret_key

    def log_activity(self, message: str):
        timestamp = datetime.utcnow().isoformat()
        hmac_value = hmac.new(self.secret_key.encode(), message.encode(), hashlib.sha256).hexdigest()
        log_entry = json.dumps({"timestamp": timestamp, "message": message, "hmac": hmac_value})
        # Assume this writes to an external secure logging service
        print(log_entry)

