class OrderDatabase:
    def __init__(self):
        self.orders = {
            "123": {"status": "shipped", "amount": 299.99},
            "456": {"status": "processing", "amount": 159.99},
            "789": {"status": "delivered", "amount": 89.99},
        }

    def get_order_status(self, order_id):
        return self.orders.get(order_id, {}).get("status", "unknown")

    def process_refund(self, order_id):
        order = self.orders.get(order_id)
        if order and order["status"] == "delivered":
            order["status"] = "refunded"
            return True
        return False

class CustomerSupportAgent(Agent):
    def __init__(self, order_db):
        self.order_db = order_db
        super().__init__(
            model="openai-gpt-4",
            tools=[
                Tool(name="Fetch Order Status", func=self.fetch_order_status),
                Tool(name="Execute Refund", func=self.execute_refund),
            ]
        )

    def fetch_order_status(self, order_id):
        status = self.order_db.get_order_status(order_id)
        if status == "unknown":
            raise ToolExecutionError(f"Order ID {order_id} not found.")
        return status

    def execute_refund(self, order_id):
        if self.order_db.process_refund(order_id):
            return f"Refund processed for order {order_id}."
        raise ToolExecutionError(f"Cannot process refund for order {order_id}. Check status.")

