import hmac
import hashlib
from autogen import Model

class AuditModel(Model):
    def __init__(self, key):
        self.key = key
        self.audit_log = []

    def predict(self, data):
        result = self._run_model(data)
        self._record_audit(data, result)
        return result

    def _run_model(self, data):
        # Simulate model prediction
        return data * 2

    def _record_audit(self, data, result):
        entry = {'input': data, 'output': result}
        entry['hmac'] = hmac.new(self.key.encode(), str(entry).encode(), hashlib.sha256).hexdigest()
        self.audit_log.append(entry)

    def verify_audit(self, entry):
        recalculated_hmac = hmac.new(self.key.encode(), str({'input': entry['input'], 'output': entry['output']}).encode(), hashlib.sha256).hexdigest()
        return recalculated_hmac == entry['hmac']

