import re
from typing import List, Dict

class Resume:
    def __init__(self, name: str, content: str):
        self.name = name
        self.content = content

class CandidateScorer:
    def __init__(self, keywords: List[str], weights: Dict[str, int]):
        self.keywords = keywords
        self.weights = weights

    def score_resume(self, resume: Resume) -> int:
        score = 0
        for keyword in self.keywords:
            occurrences = len(re.findall(r'\b{}\b'.format(re.escape(keyword)), resume.content, re.IGNORECASE))
            score += occurrences * self.weights.get(keyword, 1)
        return score

    def rank_candidates(self, resumes: List[Resume]) -> List[Dict[str, int]]:
        scored_resumes = [{'name': resume.name, 'score': self.score_resume(resume)} for resume in resumes]
        return sorted(scored_resumes, key=lambda x: x['score'], reverse=True)

# Example usage
if __name__ == "__main__":
    keywords = ['Python', 'Machine Learning', 'Project Management']
    weights = {'Python': 3, 'Machine Learning': 5, 'Project Management': 2}

    resumes = [
        Resume('Alice', "Expert in Python and Machine Learning. Experience in Project Management."),
        Resume('Bob', "Skilled in Project Management and Python."),
        Resume('Charlie', "Python developer. Machine Learning enthusiast.")
    ]

    scorer = CandidateScorer(keywords, weights)
    ranked_candidates = scorer.rank_candidates(resumes)

    for candidate in ranked_candidates:
        print(f"Candidate: {candidate['name']}, Score: {candidate['score']}")

