def log_hmac(activity):
    timestamp = datetime.now().isoformat()
    msg = f'{activity}|{timestamp}'.encode('utf-8')
    hmac_digest = hmac.new(SECRET_KEY, msg, hashlib.sha256).hexdigest()
    print(f'Activity: {activity}, Timestamp: {timestamp}, HMAC: {hmac_digest}')

def perform_analysis(data, user_consent):
    if not consent_gate.check_consent(user_consent):
        raise PermissionError("User consent not granted.")

    if injection_detector.detect(data):
        raise ValueError("Potential injection detected in data.")

    results = {}
    for agent_id in AGENT_IDS:
        agent = trust_manager.get_agent_by_id(agent_id)
        if agent:
            result = agent.analyze(data)
            results.update(result)
            log_hmac(f'{agent_id} analysis completed')

    return results

