# Define the task descriptions and roles
task_descriptions = {
    "researcher": "Conduct research on the given topic and provide a summary.",
    "writer": "Develop the initial draft based on the researcher's summary.",
    "reviewer": "Review the draft and provide feedback for improvements."
}

# Define a simple multi-agent system
class CrewAI:
    def __init__(self):
        self.tasks = Queue()
        self.results = Queue()
        self.agents = {
            "researcher": Agent(name="ResearchBot", role="researcher", task_queue=self.tasks, result_queue=self.results),
            "writer": Agent(name="WriteMaster", role="writer", task_queue=self.tasks, result_queue=self.results),
            "reviewer": Agent(name="ReviewPro", role="reviewer", task_queue=self.tasks, result_queue=self.results)
        }

    def start(self):
        for agent in self.agents.values():
            agent.start()

    def add_task(self, task):
        self.tasks.put(task)

    def get_results(self):
        while not self.results.empty():
            yield self.results.get()

class Agent(Thread):
    def __init__(self, name, role, task_queue, result_queue):
        super().__init__()
        self.name = name
        self.role = role
        self.task_queue = task_queue
        self.result_queue = result_queue
        self.active = True

    def run(self):
        while self.active:
            if not self.task_queue.empty():
                task = self.task_queue.get()
                if task["role"] == self.role:
                    result = self.perform_task(task["description"])
                    self.result_queue.put({"agent": self.name, "result": result})
                self.task_queue.task_done()
            time.sleep(random.uniform(0.1, 0.5))

    def perform_task(self, description):
        if self.role == "researcher":
            return f"{self.name} found resources on {description}."
        elif self.role == "writer":
            return f"{self.name} drafted an article on {description}."
        elif self.role == "reviewer":
            return f"{self.name} reviewed the draft and suggested changes."
        return f"{self.name} completed the task."

    def stop(self):
        self.active = False

# Example usage
if __name__ == "__main__":
    crew_ai = CrewAI()
    crew_ai.start()

    crew_ai.add_task({"role": "researcher", "description": "AI trends in healthcare"})
    crew_ai.add_task({"role": "writer", "description": "AI trends in healthcare"})
    crew_ai.add_task({"role": "reviewer", "description": "AI trends in healthcare"})

    time.sleep(2)  # Wait for some tasks to be processed

    results = list(crew_ai.get_results())
    for result in results:
        print(f"[{result['agent']}] {result['result']}")

    for agent in crew_ai.agents.values():
        agent.stop()

