from airragtrust import SourceVerifier, ApprovalGate, VariationMonitor
from transformers import AutoModelForQuestionAnswering, AutoTokenizer
import torch

class LegalDocQASystem:
    def __init__(self, model_name="distilbert-base-cased-distilled-squad"):
        self.tokenizer = AutoTokenizer.from_pretrained(model_name)
        self.model = AutoModelForQuestionAnswering.from_pretrained(model_name)
        self.source_verifier = SourceVerifier()
        self.approval_gate = ApprovalGate(allowed_sources=["trusted_legal_db.com", "regulatory.gov"])
        self.variation_monitor = VariationMonitor(threshold=0.25)

    def check_source(self, url):
        return self.source_verifier.verify(url)

    def is_allowed_source(self, url):
        return self.approval_gate.is_approved(url)

    def detect_drift(self, original_text, new_text):
        return self.variation_monitor.detect(original_text, new_text)

    def answer_question(self, question, context):
        inputs = self.tokenizer(question, context, return_tensors='pt')
        with torch.no_grad():
            outputs = self.model(**inputs)
        answer_start_idx = torch.argmax(outputs.start_logits)
        answer_end_idx = torch.argmax(outputs.end_logits) + 1
        answer = self.tokenizer.convert_tokens_to_string(
            self.tokenizer.convert_ids_to_tokens(inputs.input_ids[0][answer_start_idx:answer_end_idx])
        )
        return answer

    def process_query(self, question, document_url, document_text):
        if not self.is_allowed_source(document_url):
            raise ValueError("Source not allowed.")

        if not self.check_source(document_url):
            raise ValueError("Source verification failed.")

        detected_drift = self.detect_drift("Original document reference", document_text)
        if detected_drift:
            raise ValueError("Significant drift detected in document content.")

        return self.answer_question(question, document_text)

