import asyncio
import logging
import json
import os
from datetime import datetime
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,
    PermissionResultAllow, PermissionResultDeny,
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
os.makedirs("./audit", exist_ok=True)

DANGEROUS_COMMANDS = ["rm -rf", "sudo", "chmod 777", "mkfs"]

async def block_dangerous_bash(input_data, tool_use_id, context):
    """Block dangerous bash commands."""
    if input_data.get("tool_name") == "Bash":
        cmd = input_data.get("tool_input", {{}}).get("command", "")
        for pattern in DANGEROUS_COMMANDS:
            if pattern in cmd:
                logger.warning(f"Blocked dangerous command: {{cmd}}")
                return {{
                    "hookSpecificOutput": {{
                        "hookEventName": "PreToolUse",
                        "permissionDecision": "deny",
                        "permissionDecisionReason": f"Dangerous: {{pattern}}",
                    }}
                }}
    return {{}}

async def audit_log(input_data, tool_use_id, context):
    """Log every tool result to audit directory."""
    record = {{
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "tool": input_data.get("tool_name"),
        "tool_use_id": tool_use_id,
    }}
    fname = f"./audit/{{tool_use_id or 'unknown'}}.json"
    with open(fname, "w") as f:
        json.dump(record, f)
    return {{}}

async def permission_handler(tool_name, input_data, context):
    """Risk-based permission handler."""
    if tool_name == "Bash":
        cmd = input_data.get("command", "")
        if any(p in cmd for p in DANGEROUS_COMMANDS):
            return PermissionResultDeny(message="Blocked by policy")
    return PermissionResultAllow(updated_input=input_data)

async def main():
    options = ClaudeAgentOptions(
        allowed_tools=["Read", "Write", "Bash"],
        can_use_tool=permission_handler,
        max_turns=10,
        hooks={{
            "PreToolUse": [
                HookMatcher(matcher="Bash", hooks=[block_dangerous_bash]),
            ],
            "PostToolUse": [HookMatcher(hooks=[audit_log])],
        }},
    )
    async with ClaudeSDKClient(options=options) as client:
        await client.query("Calculate the risk score for this portfolio")
        async for message in client.receive_response():
            print(message)

asyncio.run(main())

import hmac
import hashlib
import json
import time
from threading import Thread
from AirCrewaiTrust import CrewAgent, ConsentManager, InjectionDetector

# Configuration
SECRET_KEY = b'supersecretkey'
HMAC_LOG_FILE = 'hmac_log.txt'
CONSENT_TIMEOUT = 30  # seconds

# HMAC Logging
def generate_hmac(data):
    return hmac.new(SECRET_KEY, json.dumps(data).encode('utf-8'), hashlib.sha256).hexdigest()

def log_hmac(data):
    with open(HMAC_LOG_FILE, 'a') as file:
        file.write(f"{time.time()}: {generate_hmac(data)}\n")

# Consent Gating
consent_manager = ConsentManager(timeout=CONSENT_TIMEOUT)

# Injection Detection
injection_detector = InjectionDetector()

# Crew Agents
class MarketAnalyzer(CrewAgent):
    def analyze(self, market_data):
        if not injection_detector.is_valid(market_data):
            raise ValueError("Injection detected in market data.")
        # Perform analysis
        result = {"timestamp": time.time(), "analysis": "Market is stable."}
        log_hmac(result)
        return result

class RiskEvaluator(CrewAgent):
    def evaluate(self, risk_data):
        if not injection_detector.is_valid(risk_data):
            raise ValueError("Injection detected in risk data.")
        # Perform evaluation
        result = {"timestamp": time.time(), "evaluation": "Risk is moderate."}
        log_hmac(result)
        return result

class PortfolioManager(CrewAgent):
    def manage(self, portfolio_data):
        if not injection_detector.is_valid(portfolio_data):
            raise ValueError("Injection detected in portfolio data.")
        # Perform management tasks
        result = {"timestamp": time.time(), "management": "Portfolio optimized."}
        log_hmac(result)
        return result

# Main CrewAI System
class FinancialAnalysisCrew:
    def __init__(self):
        self.market_analyzer = MarketAnalyzer()
        self.risk_evaluator = RiskEvaluator()
        self.portfolio_manager = PortfolioManager()

    def start_analysis(self, market_data, risk_data, portfolio_data):
        if not consent_manager.check_consent():
            raise PermissionError("Consent not granted for analysis.")

        market_thread = Thread(target=self.market_analyzer.analyze, args=(market_data,))
        risk_thread = Thread(target=self.risk_evaluator.evaluate, args=(risk_data,))
        portfolio_thread = Thread(target=self.portfolio_manager.manage, args=(portfolio_data,))

        market_thread.start()
        risk_thread.start()
        portfolio_thread.start()

        market_thread.join()
        risk_thread.join()
        portfolio_thread.join()

# Example usage:
if __name__ == "__main__":
