class PerformanceTracker:
    def __init__(self):
        self.student_data = {}

    def update_performance(self, student_id, subject, score):
        if student_id not in self.student_data:
            self.student_data[student_id] = {}
        if subject not in self.student_data[student_id]:
            self.student_data[student_id][subject] = []
        self.student_data[student_id][subject].append(score)

    def get_advice(self, student_id, subject):
        scores = self.student_data.get(student_id, {}).get(subject, [])
        if not scores:
            return "Let's start from the basics of this subject."
        average_score = sum(scores) / len(scores)
        if average_score >= 80:
            return "You are doing great! Let's move to advanced topics."
        elif average_score >= 60:
            return "You're doing well. Keep practicing this subject."
        else:
            return "Let's focus on fundamental concepts to improve."

