from autogen import AutoGen, Agent, Tool

# Define a tool for data loading
class DataLoaderTool(Tool):
    def run(self, source):
        import pandas as pd
        try:
            data = pd.read_csv(source)
            return data
        except Exception as e:
            return str(e)

# Define a tool for data summarization
class DataSummarizerTool(Tool):
    def run(self, dataframe):
        try:
            summary = dataframe.describe()
            return summary
        except Exception as e:
            return str(e)

# Define the assistant agent
class DataAssistant(Agent):
    def __init__(self):
        super().__init__("Data Assistant")
        self.add_tool("load_data", DataLoaderTool())
        self.add_tool("summarize_data", DataSummarizerTool())

    def process_request(self, request):
        if request['action'] == "load_data":
            return self.execute_tool("load_data", request['source'])
        elif request['action'] == "summarize_data":
            return self.execute_tool("summarize_data", request['dataframe'])

# Define the user proxy agent
class UserProxyAgent(Agent):
    def __init__(self):
        super().__init__("User Proxy")
        self.data_analysis_request = None

    def prepare_data_analysis(self, data_source):
        self.data_analysis_request = {
            'action': "load_data",
            'source': data_source
        }
        return self.data_analysis_request

    def request_data_summary(self, dataframe):
        return {
            'action': "summarize_data",
            'dataframe': dataframe
        }

# Initialize agents
assistant = DataAssistant()
user_proxy = UserProxyAgent()

# AutoGen run loop
autogen = AutoGen(
    agents=[assistant, user_proxy],
    model="gpt-3.5-turbo",
    temperature=0.7
)

