from datetime import datetime
import random

class Researcher:
    def __init__(self, name):
        self.name = name

    def conduct_research(self):
        topics = ["AI in Healthcare", "Blockchain in Finance", "Sustainability and Tech"]
        chosen_topic = random.choice(topics)
        findings = f"Research on {chosen_topic} completed with key insights."
        print(f"{self.name} conducted research on {chosen_topic}.")
        return findings

class Writer:
    def __init__(self, name):
        self.name = name

    def generate_content(self, findings):
        document = f"Article based on research findings: {findings}"
        print(f"{self.name} created content.")
        return document

class Reviewer:
    def __init__(self, name):
        self.name = name

    def review_content(self, content):
        comments = ["Excellent work!", "Needs more data.", "Good structure."]
        review = random.choice(comments)
        print(f"{self.name} reviewed the content: {review}")
        return f"Review Result: {review}, on {datetime.now().strftime('%Y-%m-%d')}"

class CrewAI:
    def __init__(self):
        self.researcher = Researcher("Dr. Smith")
        self.writer = Writer("Alice")
        self.reviewer = Reviewer("John")

    def execute_task(self):
        research_findings = self.researcher.conduct_research()
        content = self.writer.generate_content(research_findings)
        review = self.reviewer.review_content(content)
        return content, review

