import re
from typing import List, Dict
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.svm import SVC
from sklearn.pipeline import make_pipeline
import numpy as np

class ResumeEvaluator:
    def __init__(self):
        self.vectorizer = TfidfVectorizer()
        self.model = SVC(probability=True)
        self.pipeline = make_pipeline(self.vectorizer, self.model)

    def train(self, resumes: List[str], labels: List[int]) -> None:
        self.pipeline.fit(resumes, labels)

    def score_candidates(self, resumes: List[str]) -> List[float]:
        scores = self.pipeline.predict_proba(resumes)[:, 1]
        return scores.tolist()

def extract_keywords(text: str) -> List[str]:
    return re.findall(r'\b\w+\b', text.lower())

def create_training_data() -> Dict[str, List]:
    sample_resumes = [
        "Experienced software engineer with expertise in AI and ML.",
        "Project manager with a strong background in finance and budgeting.",
        "Data scientist skilled in Python, R, and data analysis.",
        "Marketing specialist with a focus on digital campaigns and SEO."
    ]
    labels = [1, 0, 1, 0]  # 1 for relevant, 0 for not relevant
    return {"resumes": sample_resumes, "labels": labels}

def main():
    evaluator = ResumeEvaluator()
    training_data = create_training_data()
    evaluator.train(training_data['resumes'], training_data['labels'])

    new_resumes = [
        "AI researcher with publications in top journals.",
        "Finance analyst with 5 years of experience in banking.",
        "Graphic designer specializing in UI/UX design.",
        "Backend developer proficient in Java and Spring."
    ]

    scores = evaluator.score_candidates(new_resumes)
    for resume, score in zip(new_resumes, scores):
        print(f"Resume: {resume}\nScore: {score:.2f}\n")

if __name__ == "__main__":
    main()

