from langchain import Agent
from langchain.prompts import PromptTemplate
from langchain.tools import Tool, ToolKit
from langchain.models import GPTModel

class AdaptiveTutorAgent(Agent):
    def __init__(self, model, tools):
        super().__init__(model, tools)
        self.student_profile = {}

    def update_profile(self, student_id, performance_data):
        if student_id not in self.student_profile:
            self.student_profile[student_id] = {
                'score_history': [],
                'current_level': 'beginner'
            }
        self.student_profile[student_id]['score_history'].append(performance_data)
        self._adjust_level(student_id)

    def _adjust_level(self, student_id):
        scores = self.student_profile[student_id]['score_history']
        avg_score = sum(scores) / len(scores)
        if avg_score > 80:
            self.student_profile[student_id]['current_level'] = 'advanced'
        elif avg_score > 50:
            self.student_profile[student_id]['current_level'] = 'intermediate'
        else:
            self.student_profile[student_id]['current_level'] = 'beginner'

    def respond_to_query(self, student_id, query):
        student_level = self.student_profile.get(student_id, {}).get('current_level', 'beginner')
        prompt = PromptTemplate(f"Provide a {student_level} level explanation for: {query}")
        return self.model.generate_response(prompt)

