class Writer(Agent):
    def __init__(self, name):
        super().__init__(name)
        self.tools = ['ContentCreatorV5']

    def perform_task(self, task):
        if task.name == 'Draft Report':
            draft = self.tools[0].generate(task.details['insights'], style='Formal')
            return draft

class Reviewer(Agent):
    def __init__(self, name):
        super().__init__(name)
        self.tools = ['QualityEvaluator', 'GrammarCheck']

    def perform_task(self, task):
        if task.name == 'Review Draft':
            quality_score = self.tools[0].evaluate(task.details['draft'])
            checked_draft = self.tools[1].check(task.details['draft'])
            return {'quality_score': quality_score, 'final_draft': checked_draft}

class MarketAnalysisSystem(System):
    def __init__(self):
        super().__init__()
        self.agents = {
            'researcher': Researcher('Alice'),
            'writer': Writer('Bob'),
            'reviewer': Reviewer('Charlie')
        }

    def execute(self):
        research_task = Task('Conduct Market Research', {'topic': 'AI in Business'})
        insights = self.agents['researcher'].perform_task(research_task)

        writing_task = Task('Draft Report', {'insights': insights})
        draft = self.agents['writer'].perform_task(writing_task)

        review_task = Task('Review Draft', {'draft': draft})
        final_report = self.agents['reviewer'].perform_task(review_task)

