        log_hmac(f'{self.name} started analysis.')

        if not consent_gate.check_consent(data.get('user_id')):
            log_hmac(f'{self.name} consent check failed.')
            raise PermissionError("User consent not obtained.")

        if injection_detector.detect(data):
            log_hmac(f'{self.name} injection detected.')
            raise ValueError("Potential injection detected in input data.")

        analysis_result = self.perform_financial_analysis(data)

        compliance_monitor.record_event(f'{self.name} completed analysis.')
        log_hmac(f'{self.name} completed analysis.')

