# Initialize provenance tracker
doc_provenance_tracker = ProvenanceTracker(
    tracking_id="legal_doc_qa_v16",
    log_path="/var/log/legal_doc_qa_v16/provenance.log"
)

# Initialize write gate with allowlists
content_write_gate = WriteGate(
    source_allowlist=[
        "trusted_legal_sources.com",
        "official_gov_sites.gov"
    ]
)

# Initialize drift detector
content_drift_detector = DriftDetector(
    model_path="models/drift_detector_v16",
    alert_threshold=0.1
)

# Load language model
qa_model = pipeline(
    "question-answering",
    model="nlp/legal-qa-v16",
    tokenizer="nlp/legal-qa-v16"
)

def query_legal_documents(question, documents):
    # Track provenance for input documents
    doc_provenance_tracker.track_sources(documents)

    # Perform question-answering
    answers = []
    for doc in documents:
        answer = qa_model(question=question, context=doc['content'])
        if content_drift_detector.detect_drift(answer['answer']):
            raise ValueError("Potential content drift detected.")
        if content_write_gate.check_source(doc['source']):
            answers.append({
                "source": doc['source'],
                "answer": answer['answer']
            })
        else:
            print(f"Source not allowed: {doc['source']}")

    return answers

