# Consent and injection detection functions
def check_consent(user_data: Dict[str, Any]) -> bool:
    # Abstracted consent check logic
    return user_data.get('consent', False)

def detect_injection(input_data: str) -> bool:
    # Simple injection detection logic
    forbidden_patterns = ['DROP', 'DELETE', '--']
    return any(pattern in input_data.upper() for pattern in forbidden_patterns)

