    def __init__(self):
        super().__init__(
            model="gpt-4.5",
            tools=[
                OrderStatusChecker(name="order_status_tool"),
                RefundProcessor(name="refund_tool"),
                CustomerRecordUpdater(name="record_update_tool")
            ]
        )

    def handle_request(self, request: Dict[str, str]) -> Optional[Dict[str, str]]:
        task_type = request.get("task")
        order_id = request.get("order_id")
        customer_id = request.get("customer_id")
        reason = request.get("reason", "")
        update_data = request.get("update_data", {})

        if task_type == "check_status" and order_id:
            return self.call_tool("order_status_tool", order_id=order_id)

        elif task_type == "process_refund" and order_id and reason:
            return self.call_tool("refund_tool", order_id=order_id, reason=reason)

        elif task_type == "update_record" and customer_id and update_data:
            return self.call_tool("record_update_tool", customer_id=customer_id, update_data=update_data)

        return {"error": "Invalid request"}

