def fetch_summary(text):
    try:
        if not text or not isinstance(text, str):
            raise ValueError("Text input must be a non-empty string.")
        response = openai.Completion.create(
            model="text-davinci-003",
            prompt=f"Summarize the following: {text}",
            temperature=0.7,
            max_tokens=50
        )
        return response.choices[0].text.strip()
    except openai.error.APIError as api_error:
        print(f"API error occurred: {api_error}")
        return ""
    except ValueError as val_error:
        print(f"Validation error: {val_error}")
        return ""
    except Exception as generic_error:
        print(f"An unexpected error occurred: {generic_error}")
        return ""

def calculate_average(numbers):
    try:
        # Input validation
        if not numbers:
            raise ValueError('The numbers list cannot be empty')
        if not all(isinstance(n, (int, float)) for n in numbers):
            raise TypeError('All elements must be int or float')
        average = sum(numbers) / len(numbers)
        return average
    except (ValueError, TypeError) as e:
        print(f'Input validation error: {e}')
        return None
    except Exception as e:
        print(f'Unexpected error: {e}')
        return None

numbers_list = [10, 20, 30]
avg = calculate_average(numbers_list)
