class PayoutRecommenderTool(Tool):
    def __init__(self, name: str):
        super().__init__(name=name)

    def process(self, context: ExecutionContext, extracted_data: list):
        # Example logic to make payout recommendations
        recommendations = []
        for data in extracted_data:
            payout = self.calculate_payout(data["claim_amount"], data["incident_details"])
            recommendations.append({
                "claim_id": data["claim_id"],
                "recommended_payout": payout
            })
        return ToolResult(success=True, data=recommendations)

