def classify_risk(risk_score):
    # Classifying risk based on score
    if risk_score > 5:
        return 'High'
    elif risk_score > 3:
        return 'Medium'
    else:
        return 'Low'

def evaluate_impact(risk_level):
    # Impact evaluation based on risk level
    if risk_level == 'High':
        return 'Severe impact'
    elif risk_level == 'Medium':
        return 'Moderate impact'
    else:
        return 'Minor impact'

import re
import json
from typing import List, Dict
from transformers import pipeline, AutoModelForSequenceClassification, AutoTokenizer

class ResumeAnalyzer:
    def __init__(self, model_name: str):
        self.tokenizer = AutoTokenizer.from_pretrained(model_name)
        self.model = AutoModelForSequenceClassification.from_pretrained(model_name)
        self.nlp_pipeline = pipeline('text-classification', model=self.model, tokenizer=self.tokenizer)

    def evaluate_resume(self, resume_text: str) -> float:
        analysis_results = self.nlp_pipeline(resume_text)
        score = analysis_results[0]['score']
        return score

    def extract_qualifications(self, resume_text: str) -> List[str]:
        pattern = r'(?:Skills:|Qualifications:)(.*?)(?:Experience:|Education:|$)'
        match = re.search(pattern, resume_text, re.IGNORECASE | re.DOTALL)
        if match:
            qualifications = match.group(1).strip().split(',')
            return [qualification.strip() for qualification in qualifications]
        return []

class CandidateScorer:
    def __init__(self, analyzer: ResumeAnalyzer):
        self.analyzer = analyzer

    def score_candidates(self, resumes: List[Dict[str, str]]) -> List[Dict[str, float]]:
        scored_candidates = []
        for resume in resumes:
            name = resume.get('name', 'Unknown')
            text = resume.get('text', '')
            score = self.analyzer.evaluate_resume(text)
            qualifications = self.analyzer.extract_qualifications(text)
            scored_candidates.append({
                'name': name,
                'score': score,
                'qualifications': qualifications
            })
        return scored_candidates

if __name__ == "__main__":
    model_version = 'bert-base-uncased-finetuned-resume'
    sample_resumes = [
        {'name': 'Alice', 'text': 'Skills: Python, AI, ML Experience: 5 years ...'},
        {'name': 'Bob', 'text': 'Skills: JavaScript, HTML, CSS Experience: 3 years ...'}
    ]

    analyzer = ResumeAnalyzer(model_name=model_version)
    scorer = CandidateScorer(analyzer=analyzer)
    results = scorer.score_candidates(sample_resumes)
    print(json.dumps(results, indent=2))

