from air_rag_trust import SourceVerifier, DocumentGate, ChangeMonitor
from typing import List, Dict
from transformers import AutoTokenizer, AutoModelForSeq2SeqLM

class LegalDocumentQASystem:
    def __init__(self, model_name: str, allowed_sources: List[str], model_version: str = "v1"):
        self.tokenizer = AutoTokenizer.from_pretrained(model_name)
        self.model = AutoModelForSeq2SeqLM.from_pretrained(model_name)
        self.source_verifier = SourceVerifier(allowed_sources)
        self.document_gate = DocumentGate()
        self.change_monitor = ChangeMonitor()
        self.model_version = model_version

    def _verify_provenance(self, document: Dict) -> bool:
        return self.source_verifier.verify(document['source'])

    def _process_document(self, document: Dict) -> bool:
        return self.document_gate.process(document)

    def _detect_drift(self, question: str, context: str) -> bool:
        return self.change_monitor.detect(question, context)

    def answer_question(self, question: str, document: Dict) -> str:
        if not self._verify_provenance(document):
            raise ValueError("Document source not allowed.")
        if not self._process_document(document):
            raise ValueError("Document failed compliance checks.")

        context = document['text']
        if self._detect_drift(question, context):
            raise ValueError("Model drift detected; reevaluation needed.")

        inputs = self.tokenizer.encode_plus(question, context, return_tensors="pt", truncation=True)
        outputs = self.model.generate(input_ids=inputs["input_ids"], attention_mask=inputs["attention_mask"])
        answer = self.tokenizer.decode(outputs[0], skip_special_tokens=True)

        return answer

# Example usage:
if __name__ == "__main__":
    model_version = "legal-qa-model-v2"
    allowed_sources = ["trusted_legal_db1", "reliable_legal_db2"]
    legal_qa_system = LegalDocumentQASystem(model_name="some-legal-model", allowed_sources=allowed_sources, model_version=model_version)

    document = {
        "source": "trusted_legal_db1",
        "text": "According to the contract law section...",
    }
    question = "What does the contract law say about breach of contract?"

    try:
        answer = legal_qa_system.answer_question(question, document)
        print("Answer:", answer)
    except ValueError as e:
        print("Error:", str(e))

