            log_file.write(f"{timestamp} | {action} | {digest}\n")

class ConsentManager:
    def __init__(self):
        self.consent_registry = {}

    def obtain_consent(self, agent_id):
        if agent_id not in self.consent_registry:
            self.consent_registry[agent_id] = self.prompt_for_consent(agent_id)
        return self.consent_registry[agent_id]

    def prompt_for_consent(self, agent_id):
        # Simulate user consent process
        print(f"Requesting consent for agent {agent_id}...")
        return True

class InjectionDetector:
    def __init__(self):
        self.detected_injections = set()

    def detect_injection(self, data):
        # Basic injection detection logic
        if ';' in data or 'DROP TABLE' in data.upper():
            self.detected_injections.add(data)
            return True
        return False

class FinancialAnalysisCrew(AirCrewAI):
    def __init__(self, secret_key):
        self.logger = Logger(secret_key)
        self.consent_manager = ConsentManager()
        self.injection_detector = InjectionDetector()
        self.agents = []
        super().__init__()

    def add_agent(self, model_version, task):
        agent_id = str(uuid.uuid4())
        if self.consent_manager.obtain_consent(agent_id):
            self.agents.append({"id": agent_id, "model_version": model_version, "task": task})
            self.logger.log_action("ADD_AGENT", f"Agent ID: {agent_id}, Model: {model_version}, Task: {task}")

    def perform_analysis(self, financial_data):
        if self.injection_detector.detect_injection(financial_data):
            self.logger.log_action("INJECTION_DETECTED", financial_data)
            return "Data injection detected, analysis aborted."

        results = []
        for agent in self.agents:
            result = self.analyze_with_agent(agent, financial_data)
            results.append(result)
            self.logger.log_action("ANALYSIS", f"Agent ID: {agent['id']}, Result: {result}")

        return results

    def analyze_with_agent(self, agent, data):
        # Simulate analysis
        return f"Analysis by {agent['model_version']} on {data}"

